def sequentialthinking(thought, thoughtNumber, totalThoughts, nextThoughtNeeded, isRevision=None, revisesThought=None, branchFromThought=None, branchId=None, needsMoreThoughts=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0550000" if __import__("os").path.isdir("./environment_mix/0550000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- Helpers
    def _log(status, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "sequentialthinking",
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_limit_ok():
        cfg = _load("service_limits.json")
        if not isinstance(cfg, dict):
            cfg = {}
        rpm = cfg.get("requests_per_minute", 0)
        if not isinstance(rpm, int):
            rpm = 0
        if rpm <= 0:
            return True, None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(minutes=1)
        c = 0
        for r in logs:
            ts = r.get("timestamp")
            if isinstance(ts, str):
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                if dt >= cutoff:
                    c += 1
        if c >= rpm:
            return False, _err("RATE_LIMIT", "Rate limit exceeded")
        return True, None

    ok_rl, rl_err = _rate_limit_ok()
    if not ok_rl:
        _log("error", "RATE_LIMIT")
        return rl_err

    # ---- Validation
    if not isinstance(thought, str) or thought.strip() == "":
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "thought must be a non-empty string")
    if not (isinstance(thoughtNumber, (int, float)) and int(thoughtNumber) == thoughtNumber):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "thoughtNumber must be an integer")
    if not (isinstance(totalThoughts, (int, float)) and int(totalThoughts) == totalThoughts):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "totalThoughts must be an integer")
    thoughtNumber = int(thoughtNumber)
    totalThoughts = int(totalThoughts)
    if thoughtNumber < 1:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "thoughtNumber must be >= 1")
    if totalThoughts < thoughtNumber:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "totalThoughts must be >= thoughtNumber")
    if not isinstance(nextThoughtNeeded, bool):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "nextThoughtNeeded must be boolean")
    if isRevision is not None and not isinstance(isRevision, bool):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "isRevision must be boolean when provided")
    if needsMoreThoughts is not None and not isinstance(needsMoreThoughts, bool):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "needsMoreThoughts must be boolean when provided")

    if revisesThought is not None:
        if not (isinstance(revisesThought, (int, float)) and int(revisesThought) == revisesThought):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "revisesThought must be an integer when provided")
        revisesThought = int(revisesThought)
        if revisesThought < 1:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "revisesThought must be >= 1")

    if branchFromThought is not None:
        if not (isinstance(branchFromThought, (int, float)) and int(branchFromThought) == branchFromThought):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "branchFromThought must be an integer when provided")
        branchFromThought = int(branchFromThought)
        if branchFromThought < 1:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "branchFromThought must be >= 1")

    if branchId is not None:
        if not isinstance(branchId, str) or branchId == "":
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "branchId must be a non-empty string when provided")
        if len(branchId) < 1 or len(branchId) > 128:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "branchId length must be between 1 and 128")

    # isRevision constraints
    if isRevision is True:
        if revisesThought is None:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "revisesThought is required when isRevision=true")
        if revisesThought > thoughtNumber:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "revisesThought cannot be greater than thoughtNumber")
    else:
        # If false or null, revisesThought must be null
        if revisesThought is not None:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "revisesThought must be null when isRevision is false or not provided")

    # Branching constraints
    if branchFromThought is not None and (branchId is None):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "branchId is required when branchFromThought is provided")
    if branchFromThought is not None and branchFromThought > thoughtNumber:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "branchFromThought must be <= thoughtNumber")

    # ---- Resolve session context (ambient auth). Prefer an active session; create one if none exists.
    sessions = _load("sessions.json")
    if not isinstance(sessions, list):
        sessions = []

    def _pick_session():
        # Prefer existing active session with most recent activity/update.
        best = None
        best_key = None
        for s in sessions:
            if not isinstance(s, dict):
                continue
            if s.get("status") != "active":
                continue
            key = s.get("last_activity_at") or s.get("updated_at") or s.get("created_at") or ""
            if best is None or key > best_key:
                best = s
                best_key = key
        return best

    session = _pick_session()
    if session is None:
        # Create a new active session
        sid = "sess_" + uuid.uuid4().hex
        session = {
            "id": sid,
            "status": "active",
            "title": None,
            "client_session_key": None,
            "last_activity_at": None,
            "total_artifacts": 0,
            "total_thoughts": 0,
            "total_branches": 0,
            "created_at": now,
            "updated_at": now,
        }
        sessions.append(session)

    session_id = session["id"]

    thoughts = _load("thoughts.json")
    if not isinstance(thoughts, list):
        thoughts = []

    # ---- Ensure branch-from exists (active thought)
    if branchFromThought is not None:
        # Allow branch-from in mainline (branch_id null) or within same branch if branching within branch
        # Here: require an active thought with thought_number == branchFromThought and (branch_id == branchId OR branch_id is null)
        found = False
        for tr in thoughts:
            if not isinstance(tr, dict):
                continue
            if tr.get("session_id") != session_id:
                continue
            if tr.get("status") != "active":
                continue
            if int(tr.get("thought_number", -1)) != branchFromThought:
                continue
            if tr.get("branch_id") == branchId or tr.get("branch_id") is None:
                found = True
                break
        if not found:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "branchFromThought must reference an existing active thought in the session")

    # ---- Uniqueness check: unique(session_id, branch_id, thought_number) where status != 'deleted'
    for tr in thoughts:
        if not isinstance(tr, dict):
            continue
        if tr.get("session_id") != session_id:
            continue
        if tr.get("status") == "deleted":
            continue
        if (tr.get("branch_id") == branchId) and int(tr.get("thought_number", -1)) == thoughtNumber:
            _log("error", "CONFLICT")
            return _err("CONFLICT", "A thought already exists at this thoughtNumber for the given branchId")

    supersedes_thought_id = None
    # ---- Revision logic: locate prior thought by (session_id, branch_id, revises_thought_number, status='active')
    if isRevision is True:
        prior = None
        for tr in thoughts:
            if not isinstance(tr, dict):
                continue
            if tr.get("session_id") != session_id:
                continue
            if tr.get("status") != "active":
                continue
            if tr.get("branch_id") != branchId:
                continue
            if int(tr.get("thought_number", -1)) != revisesThought:
                continue
            prior = tr
            break
        if prior is None:
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "No active prior thought found to revise")
        # Mark prior superseded (legal transition: active->superseded)
        prior["status"] = "superseded"
        prior["updated_at"] = now
        supersedes_thought_id = prior.get("id")

    # ---- Insert thought row
    tid = "th_" + uuid.uuid4().hex
    new_row = {
        "id": tid,
        "session_id": session_id,
        "status": "active",
        "thought": thought,
        "thought_number": thoughtNumber,
        "total_thoughts": totalThoughts,
        "next_thought_needed": nextThoughtNeeded,
        "needs_more_thoughts": needsMoreThoughts,
        "branch_id": branchId,
        "branch_from_thought_number": branchFromThought,
        "is_revision": isRevision,
        "revises_thought_number": revisesThought,
        "supersedes_thought_id": supersedes_thought_id,
        "created_at": now,
        "updated_at": now,
    }
    thoughts.append(new_row)

    # ---- Update session cached counters + last activity
    # total_thoughts = count of thoughts in session with status != deleted
    active_thoughts = [tr for tr in thoughts if isinstance(tr, dict) and tr.get("session_id") == session_id and tr.get("status") != "deleted"]
    session["total_thoughts"] = len(active_thoughts)
    # distinct non-null branch_ids among non-deleted thoughts
    branches = set()
    for tr in active_thoughts:
        bid = tr.get("branch_id")
        if bid is not None:
            branches.add(bid)
    session["total_branches"] = len(branches)
    session["last_activity_at"] = now
    session["updated_at"] = now

    # Enforce session constraints
    if session["total_thoughts"] < 0 or session["total_branches"] < 0 or session.get("total_artifacts", 0) < 0:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Session counter constraint violated")

    _save("thoughts.json", thoughts)
    _save("sessions.json", sessions)

    resp = {
        "sessionId": session_id,
        "thoughtId": tid,
        "thoughtNumber": thoughtNumber,
        "totalThoughts": totalThoughts,
        "nextThoughtNeeded": nextThoughtNeeded,
        "needsMoreThoughts": needsMoreThoughts,
        "branchId": branchId,
        "branchFromThought": branchFromThought,
        "isRevision": isRevision,
        "revisesThought": revisesThought,
        "supersedesThoughtId": supersedes_thought_id,
        "sessionTotals": {
            "totalThoughts": session["total_thoughts"],
            "totalBranches": session["total_branches"],
            "totalArtifacts": session.get("total_artifacts", 0),
            "lastActivityAt": session.get("last_activity_at"),
        },
        "createdAt": now,
    }
    _log("ok")
    return resp

def mentalmodel(modelName, problem, steps, reasoning, conclusion, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0550000" if __import__("os").path.isdir("./environment_mix/0550000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "mentalmodel",
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
        })
        _save("request_logs.json", logs)

    def _rate_limit_ok():
        cfg = _load("service_limits.json")
        if not isinstance(cfg, dict):
            cfg = {}
        rpm = cfg.get("requests_per_minute", 0)
        if not isinstance(rpm, int):
            rpm = 0
        if rpm <= 0:
            return True, None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(minutes=1)
        c = 0
        for r in logs:
            ts = r.get("timestamp")
            if isinstance(ts, str):
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                if dt >= cutoff:
                    c += 1
        if c >= rpm:
            return False, _err("RATE_LIMIT", "Rate limit exceeded")
        return True, None

    ok_rl, rl_err = _rate_limit_ok()
    if not ok_rl:
        _log("error", "RATE_LIMIT")
        return rl_err

    allowed = {"first_principles", "opportunity_cost", "error_propagation", "rubber_duck", "pareto_principle", "occams_razor"}
    if not isinstance(modelName, str) or modelName not in allowed:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "modelName must be one of the supported enums")
    if not isinstance(problem, str) or problem.strip() == "":
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "problem must be a non-empty string")
    if not (isinstance(steps, list) and all(isinstance(x, str) for x in steps)):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "steps must be an array of strings")
    if not isinstance(reasoning, str) or reasoning.strip() == "":
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "reasoning must be a non-empty string")
    if not isinstance(conclusion, str) or conclusion.strip() == "":
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "conclusion must be a non-empty string")

    sessions = _load("sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    artifacts = _load("artifacts.json")
    if not isinstance(artifacts, list):
        artifacts = []

    # pick or create an active session
    session = None
    best_key = None
    for s in sessions:
        if isinstance(s, dict) and s.get("status") == "active":
            key = s.get("last_activity_at") or s.get("updated_at") or s.get("created_at") or ""
            if session is None or key > best_key:
                session = s
                best_key = key
    if session is None:
        sid = "sess_" + uuid.uuid4().hex
        session = {
            "id": sid,
            "status": "active",
            "title": None,
            "client_session_key": None,
            "last_activity_at": None,
            "total_artifacts": 0,
            "total_thoughts": 0,
            "total_branches": 0,
            "created_at": now,
            "updated_at": now,
        }
        sessions.append(session)
    session_id = session["id"]

    payload = {
        "modelName": modelName,
        "problem": problem,
        "steps": steps,
        "reasoning": reasoning,
        "conclusion": conclusion,
    }
    if not isinstance(payload, dict):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "payload must be a valid JSON object")

    # Create artifact (tool has no external_object_id requirement)
    aid = "art_" + uuid.uuid4().hex
    row = {
        "id": aid,
        "session_id": session_id,
        "status": "active",
        "tool_name": "mentalmodel",
        "external_object_id": None,
        "iteration": None,
        "stage": None,
        "next_needed": None,
        "payload": payload,
        "created_at": now,
        "updated_at": now,
    }
    artifacts.append(row)

    # Update session counters and last_activity_at
    session["last_activity_at"] = now
    session["updated_at"] = now
    session["total_artifacts"] = len([a for a in artifacts if isinstance(a, dict) and a.get("session_id") == session_id and a.get("status") != "deleted"])
    if session["total_artifacts"] < 0:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Session counter constraint violated")

    _save("artifacts.json", artifacts)
    _save("sessions.json", sessions)

    _log("ok")
    return {
        "sessionId": session_id,
        "artifact": row,
    }

def debuggingapproach(approachName, issue, steps, findings, resolution, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0550000" if __import__("os").path.isdir("./environment_mix/0550000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "debuggingapproach",
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
        })
        _save("request_logs.json", logs)

    def _rate_limit_ok():
        cfg = _load("service_limits.json")
        if not isinstance(cfg, dict):
            cfg = {}
        rpm = cfg.get("requests_per_minute", 0)
        if not isinstance(rpm, int):
            rpm = 0
        if rpm <= 0:
            return True, None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(minutes=1)
        c = 0
        for r in logs:
            ts = r.get("timestamp")
            if isinstance(ts, str):
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                if dt >= cutoff:
                    c += 1
        if c >= rpm:
            return False, _err("RATE_LIMIT", "Rate limit exceeded")
        return True, None

    ok_rl, rl_err = _rate_limit_ok()
    if not ok_rl:
        _log("error", "RATE_LIMIT")
        return rl_err

    # Quota: max artifacts per session if configured
    def _quota_ok(session_id, artifacts_rows):
        cfg = _load("service_limits.json")
        if not isinstance(cfg, dict):
            cfg = {}
        max_art = cfg.get("max_artifacts_per_session", None)
        if max_art is None:
            return True, None
        if not isinstance(max_art, int) or max_art < 0:
            return True, None
        count = 0
        for a in artifacts_rows:
            if isinstance(a, dict) and a.get("session_id") == session_id and a.get("status") != "deleted":
                count += 1
        if count >= max_art:
            return False, _err("QUOTA_EXCEEDED", "Artifact quota exceeded for session")
        return True, None

    allowed = {
        "binary_search", "reverse_engineering", "divide_conquer", "backtracking", "cause_elimination",
        "program_slicing", "log_analysis", "static_analysis", "root_cause_analysis", "delta_debugging",
        "fuzzing", "incremental_testing"
    }
    if not isinstance(approachName, str) or approachName not in allowed:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "approachName must be one of the supported enums")
    if not isinstance(issue, str) or issue.strip() == "":
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "issue must be a non-empty string")
    if not (isinstance(steps, list) and all(isinstance(x, str) for x in steps)):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "steps must be an array of strings")
    if not isinstance(findings, str) or findings.strip() == "":
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "findings must be a non-empty string")
    if not isinstance(resolution, str) or resolution.strip() == "":
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "resolution must be a non-empty string")

    sessions = _load("sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    artifacts = _load("artifacts.json")
    if not isinstance(artifacts, list):
        artifacts = []

    # pick or create an active session
    session = None
    best_key = None
    for s in sessions:
        if isinstance(s, dict) and s.get("status") == "active":
            key = s.get("last_activity_at") or s.get("updated_at") or s.get("created_at") or ""
            if session is None or key > best_key:
                session = s
                best_key = key
    if session is None:
        sid = "sess_" + uuid.uuid4().hex
        session = {
            "id": sid,
            "status": "active",
            "title": None,
            "client_session_key": None,
            "last_activity_at": None,
            "total_artifacts": 0,
            "total_thoughts": 0,
            "total_branches": 0,
            "created_at": now,
            "updated_at": now,
        }
        sessions.append(session)
    session_id = session["id"]

    ok_q, q_err = _quota_ok(session_id, artifacts)
    if not ok_q:
        _log("error", "QUOTA_EXCEEDED")
        return q_err

    payload = {
        "approachName": approachName,
        "issue": issue,
        "steps": steps,
        "findings": findings,
        "resolution": resolution,
    }

    aid = "art_" + uuid.uuid4().hex
    row = {
        "id": aid,
        "session_id": session_id,
        "status": "active",
        "tool_name": "debuggingapproach",
        "external_object_id": None,
        "iteration": None,
        "stage": None,
        "next_needed": None,
        "payload": payload,
        "created_at": now,
        "updated_at": now,
    }
    artifacts.append(row)

    session["last_activity_at"] = now
    session["updated_at"] = now
    session["total_artifacts"] = len([a for a in artifacts if isinstance(a, dict) and a.get("session_id") == session_id and a.get("status") != "deleted"])
    if session["total_artifacts"] < 0:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Session counter constraint violated")

    _save("artifacts.json", artifacts)
    _save("sessions.json", sessions)

    _log("ok")
    return {
        "sessionId": session_id,
        "artifact": row,
    }

def collaborativereasoning(topic, personas, contributions, stage, activePersonaId, sessionId, iteration, nextContributionNeeded, **_extra):
