                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "collaborativereasoning",
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
        })
        _save("request_logs.json", logs)

    def _rate_limit_ok():
        cfg = _load("service_limits.json")
        if not isinstance(cfg, dict):
            cfg = {}
        rpm = cfg.get("requests_per_minute", 0)
        if not isinstance(rpm, int):
            rpm = 0
        if rpm <= 0:
            return True, None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(minutes=1)
        c = 0
        for r in logs:
            ts = r.get("timestamp")
            if isinstance(ts, str):
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                if dt >= cutoff:
                    c += 1
        if c >= rpm:
            return False, _err("RATE_LIMIT", "Rate limit exceeded")
        return True, None

    ok_rl, rl_err = _rate_limit_ok()
    if not ok_rl:
        _log("error", "RATE_LIMIT")
        return rl_err

    # ---- Validate
    if not isinstance(topic, str) or topic.strip() == "":
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "topic must be a non-empty string")
    if not isinstance(sessionId, str) or sessionId.strip() == "":
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sessionId must be a non-empty string")
    if not (isinstance(iteration, (int, float)) and int(iteration) == iteration):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "iteration must be an integer")
    iteration = int(iteration)
    if iteration < 0:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "iteration must be >= 0")
    if not isinstance(nextContributionNeeded, bool):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "nextContributionNeeded must be boolean")
    allowed_stages = {"problem-definition", "ideation", "critique", "integration", "decision", "reflection"}
    if not isinstance(stage, str) or stage not in allowed_stages:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "stage must be one of the allowed enums")
    if not isinstance(activePersonaId, str) or activePersonaId.strip() == "":
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "activePersonaId must be a non-empty string")

    if not isinstance(personas, list):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "personas must be an array")
    if not isinstance(contributions, list):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "contributions must be an array")

    style_allowed = {"formal", "casual", "technical", "creative"}
    tone_allowed = {"analytical", "supportive", "challenging", "neutral"}
    contrib_type_allowed = {"observation", "question", "insight", "concern", "suggestion", "challenge", "synthesis"}

    persona_ids = []
    for p in personas:
        if not isinstance(p, dict):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Each persona must be an object")
        for k in ["id", "name", "expertise", "background", "perspective", "biases", "communication"]:
            if k not in p:
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"Persona missing required field: {k}")
        if not isinstance(p["id"], str) or p["id"].strip() == "":
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "persona.id must be a non-empty string")
        if p["id"] in persona_ids:
            _log("error", "CONFLICT")
            return _err("CONFLICT", "Duplicate persona.id in personas array")
        persona_ids.append(p["id"])
        if not isinstance(p["name"], str) or p["name"].strip() == "":
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "persona.name must be a non-empty string")
        if not (isinstance(p["expertise"], list) and all(isinstance(x, str) for x in p["expertise"])):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "persona.expertise must be an array of strings")
        if not isinstance(p["background"], str):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "persona.background must be a string")
        if not isinstance(p["perspective"], str):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "persona.perspective must be a string")
        if not (isinstance(p["biases"], list) and all(isinstance(x, str) for x in p["biases"])):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "persona.biases must be an array of strings")
        comm = p["communication"]
        if not isinstance(comm, dict):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "persona.communication must be an object")
        if "style" not in comm or "tone" not in comm:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "persona.communication must include style and tone")
        if comm["style"] not in style_allowed:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "persona.communication.style invalid")
        if comm["tone"] not in tone_allowed:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "persona.communication.tone invalid")

    if activePersonaId not in set(persona_ids):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "activePersonaId must exist among personas")

    for c in contributions:
        if not isinstance(c, dict):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Each contribution must be an object")
        for k in ["personaId", "content", "type", "confidence"]:
            if k not in c:
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"Contribution missing required field: {k}")
        if not isinstance(c["personaId"], str) or c["personaId"].strip() == "":
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "contribution.personaId must be a non-empty string")
        if c["personaId"] not in set(persona_ids):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "All contributions must reference a personaId that exists among personas")
        if not isinstance(c["content"], str) or c["content"].strip() == "":
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "contribution.content must be a non-empty string")
        if c["type"] not in contrib_type_allowed:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "contribution.type invalid")
        conf = c["confidence"]
        if not isinstance(conf, (int, float)):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "contribution.confidence must be a number")
        if conf < 0 or conf > 1:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "contribution.confidence must be within [0,1]")
        if "referenceIds" in c:
            if not (isinstance(c["referenceIds"], list) and all(isinstance(x, str) for x in c["referenceIds"])):
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "contribution.referenceIds must be an array of strings when provided")

    # ---- Load store
    sessions = _load("sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    collab_sessions = _load("collaboration_sessions.json")
    if not isinstance(collab_sessions, list):
        collab_sessions = []
    collab_entities = _load("collaboration_entities.json")
    if not isinstance(collab_entities, list):
        collab_entities = []

    # ---- Find owning session by provided sessionId
    sess_row = None
    for s in sessions:
        if isinstance(s, dict) and s.get("id") == sessionId and s.get("status") != "deleted":
            sess_row = s
            break
    if sess_row is None:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "sessionId not found")

    # ---- Upsert collaboration_session by (session_id, external_session_id) where status != deleted
    external_session_id = sessionId  # tool uses "sessionId" as its external id
    cs = None
    for r in collab_sessions:
        if not isinstance(r, dict):
            continue
        if r.get("session_id") == sessionId and r.get("external_session_id") == external_session_id and r.get("status") != "deleted":
            cs = r
            break

    if cs is None:
        cs = {
            "id": "colses_" + uuid.uuid4().hex,
            "session_id": sessionId,
            "external_session_id": external_session_id,
            "status": "active",
            "topic": topic,
            "stage": stage,
            "active_persona_id": activePersonaId,
            "iteration": iteration,
            "next_contribution_needed": nextContributionNeeded,
            "created_at": now,
            "updated_at": now,
        }
        collab_sessions.append(cs)
    else:
        # lifecycle: do not update if deleted; if completed, allow update? schema says completed->deleted only,
        # so updating completed would be invalid.
        if cs.get("status") != "active":
            _log("error", "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", "Cannot update a non-active collaboration session")
        cs["topic"] = topic
        cs["stage"] = stage
        cs["active_persona_id"] = activePersonaId
        cs["iteration"] = iteration
        cs["next_contribution_needed"] = nextContributionNeeded
        cs["updated_at"] = now

    collab_session_id = cs["id"]

    # ---- Upsert persona entity rows (unique(collaboration_session_id, entity_type, persona_id) where entity_type='persona')
    existing_persona_rows = {}
    for e in collab_entities:
        if isinstance(e, dict) and e.get("collaboration_session_id") == collab_session_id and e.get("entity_type") == "persona":
            existing_persona_rows[e.get("persona_id")] = e

    for p in personas:
        pid = p["id"]
        comm = p["communication"]
        if pid in existing_persona_rows:
            e = existing_persona_rows[pid]
            e["persona_name"] = p["name"]
            e["persona_expertise"] = p["expertise"]
            e["persona_background"] = p["background"]
            e["persona_perspective"] = p["perspective"]
            e["persona_biases"] = p["biases"]
            e["persona_comm_style"] = comm["style"]
            e["persona_comm_tone"] = comm["tone"]
            e["iteration"] = iteration
            e["updated_at"] = now
        else:
            collab_entities.append({
                "id": "colent_" + uuid.uuid4().hex,
                "collaboration_session_id": collab_session_id,
                "entity_type": "persona",
                "persona_id": pid,
                "persona_name": p["name"],
                "persona_expertise": p["expertise"],
                "persona_background": p["background"],
                "persona_perspective": p["perspective"],
                "persona_biases": p["biases"],
                "persona_comm_style": comm["style"],
                "persona_comm_tone": comm["tone"],
                "contribution_type": None,
                "contribution_content": None,
                "contribution_confidence": None,
                "reference_ids": None,
                "iteration": iteration,
                "created_at": now,
                "updated_at": now,
            })

    # ---- Validate persona existence for contributions within same collaboration_session_id (store-level)
    persona_set = set()
    for e in collab_entities:
        if isinstance(e, dict) and e.get("collaboration_session_id") == collab_session_id and e.get("entity_type") == "persona":
            if isinstance(e.get("persona_id"), str):
                persona_set.add(e["persona_id"])
    if activePersonaId not in persona_set:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "activePersonaId must exist as a persona row within this collaboration session")

    # ---- Append contribution rows (no uniqueness constraint)
    for c in contributions:
        if c["personaId"] not in persona_set:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Contribution personaId must exist as persona row within this collaboration session")
        collab_entities.append({
            "id": "colent_" + uuid.uuid4().hex,
            "collaboration_session_id": collab_session_id,
            "entity_type": "contribution",
            "persona_id": c["personaId"],
            "persona_name": None,
            "persona_expertise": None,
            "persona_background": None,
            "persona_perspective": None,
            "persona_biases": None,
            "persona_comm_style": None,
            "persona_comm_tone": None,
            "contribution_type": c["type"],
            "contribution_content": c["content"],
            "contribution_confidence": c["confidence"],
            "reference_ids": c.get("referenceIds"),
            "iteration": iteration,
            "created_at": now,
            "updated_at": now,
        })

    # ---- Update session last activity
    sess_row["last_activity_at"] = now
    sess_row["updated_at"] = now

    _save("collaboration_sessions.json", collab_sessions)
    _save("collaboration_entities.json", collab_entities)
    _save("sessions.json", sessions)

    # ---- Return stored state for this collab session (personas + contributions for this iteration)
    out_personas = []
    for e in collab_entities:
        if not isinstance(e, dict):
            continue
        if e.get("collaboration_session_id") != collab_session_id:
            continue
        if e.get("entity_type") != "persona":
            continue
        out_personas.append({
            "id": e.get("persona_id"),
            "name": e.get("persona_name"),
            "expertise": e.get("persona_expertise"),
            "background": e.get("persona_background"),
            "perspective": e.get("persona_perspective"),
            "biases": e.get("persona_biases"),
            "communication": {
                "style": e.get("persona_comm_style"),
                "tone": e.get("persona_comm_tone"),
            }
        })

    out_contribs = []
    for e in collab_entities:
        if not isinstance(e, dict):
            continue
        if e.get("collaboration_session_id") != collab_session_id:
            continue
        if e.get("entity_type") != "contribution":
            continue
        if e.get("iteration") != iteration:
            continue
        out_contribs.append({
            "personaId": e.get("persona_id"),
            "content": e.get("contribution_content"),
            "type": e.get("contribution_type"),
            "confidence": e.get("contribution_confidence"),
            "referenceIds": e.get("reference_ids"),
        })

    resp = {
        "sessionId": sessionId,
        "discussion": {
            "id": cs.get("id"),
            "externalSessionId": cs.get("external_session_id"),
            "status": cs.get("status"),
            "topic": cs.get("topic"),
            "stage": cs.get("stage"),
            "activePersonaId": cs.get("active_persona_id"),
            "iteration": cs.get("iteration"),
            "nextContributionNeeded": cs.get("next_contribution_needed"),
            "personas": out_personas,
            "contributions": out_contribs,
            "createdAt": cs.get("created_at"),
            "updatedAt": cs.get("updated_at"),
        }
    }
    _log("ok")
    return resp

def decisionframework(decisionStatement, options, analysisType, stage, decisionId, iteration, nextStageNeeded, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0550000" if __import__("os").path.isdir("./environment_mix/0550000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Minimal request log (schema not provided; best-effort, non-fatal)
    def _log(status, code=None, message=None, artifact_id=None):
        try:
            logs = _load("request_logs.json")
            logs.append(
                {
                    "id": "req_" + uuid.uuid4().hex,
                    "endpoint": "decisionframework",
                    "status": status,
                    "error_code": code,
                    "error_message": message,
                    "artifact_id": artifact_id,
                    "timestamp": now,
                    "latency_ms": int((time.time() - t0) * 1000),
                }
            )
            _save("request_logs.json", logs)
        except Exception:
            return

    # Validate inputs per JSON schema
    if not isinstance(decisionStatement, str):
        _log("error", "VALIDATION_ERROR", "decisionStatement must be a string")
        return _err("VALIDATION_ERROR", "decisionStatement must be a string")
    if not isinstance(options, list):
        _log("error", "VALIDATION_ERROR", "options must be an array")
        return _err("VALIDATION_ERROR", "options must be an array")
    for i, opt in enumerate(options):
        if not isinstance(opt, dict):
            _log("error", "VALIDATION_ERROR", f"options[{i}] must be an object")
            return _err("VALIDATION_ERROR", f"options[{i}] must be an object")
        if set(opt.keys()) - {"name", "description"}:
            _log("error", "VALIDATION_ERROR", f"options[{i}] has additional properties")
            return _err("VALIDATION_ERROR", f"options[{i}] has additional properties")
        if "name" not in opt or "description" not in opt:
            _log("error", "VALIDATION_ERROR", f"options[{i}] must include name and description")
            return _err("VALIDATION_ERROR", f"options[{i}] must include name and description")
        if not isinstance(opt.get("name"), str) or not isinstance(opt.get("description"), str):
            _log("error", "VALIDATION_ERROR", f"options[{i}].name and .description must be strings")
            return _err("VALIDATION_ERROR", f"options[{i}].name and .description must be strings")
    if not isinstance(analysisType, str):
        _log("error", "VALIDATION_ERROR", "analysisType must be a string")
        return _err("VALIDATION_ERROR", "analysisType must be a string")
    if not isinstance(stage, str):
        _log("error", "VALIDATION_ERROR", "stage must be a string")
        return _err("VALIDATION_ERROR", "stage must be a string")
    if not isinstance(decisionId, str) or not (1 <= len(decisionId) <= 128):
        _log("error", "VALIDATION_ERROR", "decisionId must be a string length 1..128")
        return _err("VALIDATION_ERROR", "decisionId must be a string length 1..128")
    if not (isinstance(iteration, int) or isinstance(iteration, float)) or isinstance(iteration, bool):
        _log("error", "VALIDATION_ERROR", "iteration must be a number")
        return _err("VALIDATION_ERROR", "iteration must be a number")
    if iteration < 0:
        _log("error", "VALIDATION_ERROR", "iteration must be >= 0")
        return _err("VALIDATION_ERROR", "iteration must be >= 0")
    if not isinstance(nextStageNeeded, bool):
        _log("error", "VALIDATION_ERROR", "nextStageNeeded must be a boolean")
        return _err("VALIDATION_ERROR", "nextStageNeeded must be a boolean")

    # Must have a usable session context but tool surface has none.
    # Choose a non-deleted session that can accept writes; if none exists, refuse.
    sessions = _load("sessions.json")
    active_sessions = [s for s in sessions if isinstance(s, dict) and s.get("status") == "active"]
    if not active_sessions:
        _log("error", "UNAUTHORIZED", "No active session available for this call")
        return _err("UNAUTHORIZED", "No active session available for this call")

    # Pick the active session with most recent activity, else newest created
    def _ts(x):
        v = x.get("last_activity_at") or x.get("updated_at") or x.get("created_at") or ""
        return v

    active_sessions.sort(key=_ts, reverse=True)
    session = active_sessions[0]
    session_id = session.get("id")
    if not isinstance(session_id, str) or not session_id:
        _log("error", "UNAUTHORIZED", "No valid session available for this call")
        return _err("UNAUTHORIZED", "No valid session available for this call")

    artifacts = _load("artifacts.json")

    # Enforce unique(session_id, tool_name, external_object_id) where external_object_id not null and status!='deleted'
    existing = None
    for a in artifacts:
        if (
            isinstance(a, dict)
            and a.get("session_id") == session_id
            and a.get("tool_name") == "decisionframework"
            and a.get("external_object_id") == decisionId
            and a.get("status") != "deleted"
        ):
            existing = a
            break

    payload = {
        "decisionStatement": decisionStatement,
        "options": options,
        "analysisType": analysisType,
        "stage": stage,
        "decisionId": decisionId,
        "iteration": iteration,
        "nextStageNeeded": nextStageNeeded,
    }

    # Validate artifact constraint: payload must be object; and decisionframework implies external_object_id matches payload.decisionId
    if payload.get("decisionId") != decisionId:
        _log("error", "VALIDATION_ERROR", "decisionId must match payload.decisionId")
        return _err("VALIDATION_ERROR", "decisionId must match payload.decisionId")

    if existing is None:
        new_id = "art_" + uuid.uuid4().hex
        row = {
            "id": new_id,
            "session_id": session_id,
            "status": "active",
            "tool_name": "decisionframework",
            "external_object_id": decisionId,
            "iteration": iteration,
            "stage": stage,
            "next_needed": nextStageNeeded,
            "payload": payload,
            "created_at": now,
            "updated_at": now,
        }
        artifacts.append(row)

        # Update session cached counters and last_activity_at
        session["last_activity_at"] = now
        session["updated_at"] = now
        try:
            session["total_artifacts"] = int(session.get("total_artifacts", 0)) + 1
        except Exception:
            session["total_artifacts"] = 1

        _save("artifacts.json", artifacts)
        _save("sessions.json", sessions)

        _log("ok", artifact_id=new_id)
        # Return stored artifact (client-visible)
        return {
            "decisionStatement": decisionStatement,
            "options": options,
            "analysisType": analysisType,
            "stage": stage,
            "decisionId": decisionId,
            "iteration": iteration,
            "nextStageNeeded": nextStageNeeded,
        }

    # Update existing (same natural key). Keep created_at; update updated_at.
    existing["iteration"] = iteration
    existing["stage"] = stage
    existing["next_needed"] = nextStageNeeded
    existing["payload"] = payload
    existing["updated_at"] = now
    if existing.get("status") == "deleted":
        # Should not happen due to filter above, but guard.
        _log("error", "NOT_FOUND", "Artifact not found")
        return _err("NOT_FOUND", "Artifact not found")

    session["last_activity_at"] = now
    session["updated_at"] = now

    _save("artifacts.json", artifacts)
    _save("sessions.json", sessions)

    _log("ok", artifact_id=existing.get("id"))
    return {
        "decisionStatement": decisionStatement,
        "options": options,
        "analysisType": analysisType,
        "stage": stage,
        "decisionId": decisionId,
        "iteration": iteration,
        "nextStageNeeded": nextStageNeeded,
    }

def metacognitivemonitoring(task, stage, overallConfidence, uncertaintyAreas, recommendedApproach, monitoringId, iteration, nextAssessmentNeeded, **_extra):
