                    "error_code": code,
                    "error_message": message,
                    "artifact_id": artifact_id,
                    "timestamp": now,
                    "latency_ms": int((time.time() - t0) * 1000),
                }
            )
            _save("request_logs.json", logs)
        except Exception:
            return

    # Validate schema
    if not isinstance(task, str):
        _log("error", "VALIDATION_ERROR", "task must be a string")
        return _err("VALIDATION_ERROR", "task must be a string")
    if not isinstance(stage, str):
        _log("error", "VALIDATION_ERROR", "stage must be a string")
        return _err("VALIDATION_ERROR", "stage must be a string")
    if not (isinstance(overallConfidence, int) or isinstance(overallConfidence, float)) or isinstance(overallConfidence, bool):
        _log("error", "VALIDATION_ERROR", "overallConfidence must be a number")
        return _err("VALIDATION_ERROR", "overallConfidence must be a number")
    if not isinstance(uncertaintyAreas, list) or any(not isinstance(x, str) for x in uncertaintyAreas):
        _log("error", "VALIDATION_ERROR", "uncertaintyAreas must be an array of strings")
        return _err("VALIDATION_ERROR", "uncertaintyAreas must be an array of strings")
    if not isinstance(recommendedApproach, str):
        _log("error", "VALIDATION_ERROR", "recommendedApproach must be a string")
        return _err("VALIDATION_ERROR", "recommendedApproach must be a string")
    if not isinstance(monitoringId, str) or not (1 <= len(monitoringId) <= 128):
        _log("error", "VALIDATION_ERROR", "monitoringId must be a string length 1..128")
        return _err("VALIDATION_ERROR", "monitoringId must be a string length 1..128")
    if not (isinstance(iteration, int) or isinstance(iteration, float)) or isinstance(iteration, bool):
        _log("error", "VALIDATION_ERROR", "iteration must be a number")
        return _err("VALIDATION_ERROR", "iteration must be a number")
    if iteration < 0:
        _log("error", "VALIDATION_ERROR", "iteration must be >= 0")
        return _err("VALIDATION_ERROR", "iteration must be >= 0")
    if not isinstance(nextAssessmentNeeded, bool):
        _log("error", "VALIDATION_ERROR", "nextAssessmentNeeded must be a boolean")
        return _err("VALIDATION_ERROR", "nextAssessmentNeeded must be a boolean")

    sessions = _load("sessions.json")
    active_sessions = [s for s in sessions if isinstance(s, dict) and s.get("status") == "active"]
    if not active_sessions:
        _log("error", "UNAUTHORIZED", "No active session available for this call")
        return _err("UNAUTHORIZED", "No active session available for this call")

    def _ts(x):
        v = x.get("last_activity_at") or x.get("updated_at") or x.get("created_at") or ""
        return v

    active_sessions.sort(key=_ts, reverse=True)
    session = active_sessions[0]
    session_id = session.get("id")
    if not isinstance(session_id, str) or not session_id:
        _log("error", "UNAUTHORIZED", "No valid session available for this call")
        return _err("UNAUTHORIZED", "No valid session available for this call")

    artifacts = _load("artifacts.json")

    existing = None
    for a in artifacts:
        if (
            isinstance(a, dict)
            and a.get("session_id") == session_id
            and a.get("tool_name") == "metacognitivemonitoring"
            and a.get("external_object_id") == monitoringId
            and a.get("status") != "deleted"
        ):
            existing = a
            break

    payload = {
        "task": task,
        "stage": stage,
        "overallConfidence": overallConfidence,
        "uncertaintyAreas": uncertaintyAreas,
        "recommendedApproach": recommendedApproach,
        "monitoringId": monitoringId,
        "iteration": iteration,
        "nextAssessmentNeeded": nextAssessmentNeeded,
    }

    # Constraint: tool_name='metacognitivemonitoring' implies external_object_id not null and payload.monitoringId=external_object_id
    if payload.get("monitoringId") != monitoringId:
        _log("error", "VALIDATION_ERROR", "monitoringId must match payload.monitoringId")
        return _err("VALIDATION_ERROR", "monitoringId must match payload.monitoringId")

    if existing is None:
        new_id = "art_" + uuid.uuid4().hex
        row = {
            "id": new_id,
            "session_id": session_id,
            "status": "active",
            "tool_name": "metacognitivemonitoring",
            "external_object_id": monitoringId,
            "iteration": iteration,
            "stage": stage,
            "next_needed": nextAssessmentNeeded,
            "payload": payload,
            "created_at": now,
            "updated_at": now,
        }
        artifacts.append(row)

        session["last_activity_at"] = now
        session["updated_at"] = now
        try:
            session["total_artifacts"] = int(session.get("total_artifacts", 0)) + 1
        except Exception:
            session["total_artifacts"] = 1

        _save("artifacts.json", artifacts)
        _save("sessions.json", sessions)

        _log("ok", artifact_id=new_id)
        return {
            "task": task,
            "stage": stage,
            "overallConfidence": overallConfidence,
            "uncertaintyAreas": uncertaintyAreas,
            "recommendedApproach": recommendedApproach,
            "monitoringId": monitoringId,
            "iteration": iteration,
            "nextAssessmentNeeded": nextAssessmentNeeded,
        }

    # Update existing
    existing["iteration"] = iteration
    existing["stage"] = stage
    existing["next_needed"] = nextAssessmentNeeded
    existing["payload"] = payload
    existing["updated_at"] = now

    session["last_activity_at"] = now
    session["updated_at"] = now

    _save("artifacts.json", artifacts)
    _save("sessions.json", sessions)

    _log("ok", artifact_id=existing.get("id"))
    return {
        "task": task,
        "stage": stage,
        "overallConfidence": overallConfidence,
        "uncertaintyAreas": uncertaintyAreas,
        "recommendedApproach": recommendedApproach,
        "monitoringId": monitoringId,
        "iteration": iteration,
        "nextAssessmentNeeded": nextAssessmentNeeded,
    }

