def creativethinking(prompt, ideas, techniques, connections, insights, sessionId, iteration, nextIdeaNeeded, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0550000" if __import__("os").path.isdir("./environment_mix/0550000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_request_log(status, error_code=None, error_message=None, meta=None):
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "creativethinking",
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": latency_ms,
            "timestamp": now,
        }
        if isinstance(meta, dict):
            row["meta"] = meta
        for fname in ("request_logs.json", "requests.json", "usage.json", "audit_logs.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                data = _load(fname)
                if isinstance(data, list):
                    data.append(row)
                    _save(fname, data)
                elif isinstance(data, dict) and isinstance(data.get("requests"), list):
                    data["requests"].append(row)
                    _save(fname, data)
                break

    def _rate_limit_check():
        # Best-effort; if no rate limit config/log exists, allow.
        cfg = _load("rate_limits.json")
        if not isinstance(cfg, dict):
            cfg = {}
        rate = cfg.get("rate_limit_per_minute")
        quota = cfg.get("daily_quota")
        if rate is None and quota is None:
            return None

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
        minute_ago = now_dt - datetime.timedelta(seconds=60)
        day_ago = now_dt - datetime.timedelta(days=1)

        def _parse_ts(s):
            if not isinstance(s, str):
                return None
            try:
                return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            except Exception:
                return None

        count_min = 0
        count_day = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != "creativethinking":
                continue
            ts = _parse_ts(r.get("timestamp"))
            if not ts:
                continue
            if ts >= minute_ago:
                count_min += 1
            if ts >= day_ago:
                count_day += 1

        if isinstance(rate, int) and rate >= 0 and count_min >= rate:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        if isinstance(quota, int) and quota >= 0 and count_day >= quota:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    # Quota/rate check first (observable dynamics still require logging on return)
    rl = _rate_limit_check()
    if rl:
        _append_request_log("error", rl["error"]["code"], rl["error"]["message"])
        return rl

    # Validate inputs
    if not isinstance(prompt, str) or not prompt:
        _append_request_log("error", "VALIDATION_ERROR", "prompt must be a non-empty string")
        return _err("VALIDATION_ERROR", "prompt must be a non-empty string")
    for name, arr in (("ideas", ideas), ("techniques", techniques), ("connections", connections), ("insights", insights)):
        if not isinstance(arr, list) or any(not isinstance(x, str) for x in arr):
            _append_request_log("error", "VALIDATION_ERROR", f"{name} must be an array of strings")
            return _err("VALIDATION_ERROR", f"{name} must be an array of strings")
    if not isinstance(sessionId, str) or not sessionId:
        _append_request_log("error", "VALIDATION_ERROR", "sessionId must be a non-empty string")
        return _err("VALIDATION_ERROR", "sessionId must be a non-empty string")
    if not isinstance(iteration, (int, float)) or isinstance(iteration, bool):
        _append_request_log("error", "VALIDATION_ERROR", "iteration must be a number")
        return _err("VALIDATION_ERROR", "iteration must be a number")
    if iteration < 0:
        _append_request_log("error", "VALIDATION_ERROR", "iteration must be >= 0")
        return _err("VALIDATION_ERROR", "iteration must be >= 0")
    if not isinstance(nextIdeaNeeded, bool):
        _append_request_log("error", "VALIDATION_ERROR", "nextIdeaNeeded must be a boolean")
        return _err("VALIDATION_ERROR", "nextIdeaNeeded must be a boolean")

    sessions = _load("sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    srow = next((s for s in sessions if isinstance(s, dict) and s.get("id") == sessionId), None)
    if not srow or srow.get("status") == "deleted":
        _append_request_log("error", "NOT_FOUND", "sessionId not found")
        return _err("NOT_FOUND", "sessionId not found")

    artifacts = _load("artifacts.json")
    if not isinstance(artifacts, list):
        artifacts = []

    # For creativethinking, external_object_id is null; do NOT enforce "next expected iteration"
    # (real API allows setting iteration; uniqueness is not iteration-based in schema).
    payload = {
        "prompt": prompt,
        "ideas": ideas,
        "techniques": techniques,
        "connections": connections,
        "insights": insights,
        "iteration": iteration,
        "nextIdeaNeeded": nextIdeaNeeded,
    }

    # Create artifact row
    art_id = "ct_art_" + uuid.uuid4().hex[:26]
    row = {
        "id": art_id,
        "session_id": sessionId,
        "status": "active",
        "tool_name": "creativethinking",
        "external_object_id": None,
        "iteration": iteration,
        "stage": None,
        "next_needed": nextIdeaNeeded,
        "payload": payload,
        "created_at": now,
        "updated_at": now,
    }

    artifacts.append(row)
    _save("artifacts.json", artifacts)

    # Update session cached counters + last_activity_at
    srow["last_activity_at"] = now
    srow["updated_at"] = now
    if not isinstance(srow.get("total_artifacts"), int) or srow.get("total_artifacts") < 0:
        # Recompute if corrupted
        srow["total_artifacts"] = sum(
            1 for a in artifacts
            if isinstance(a, dict) and a.get("session_id") == sessionId and a.get("status") != "deleted"
        )
    else:
        srow["total_artifacts"] += 1
    if not isinstance(srow.get("total_thoughts"), int) or srow.get("total_thoughts") < 0:
        srow["total_thoughts"] = max(0, srow.get("total_thoughts") or 0)
    if not isinstance(srow.get("total_branches"), int) or srow.get("total_branches") < 0:
        srow["total_branches"] = max(0, srow.get("total_branches") or 0)

    _save("sessions.json", sessions)

    _append_request_log("success", meta={"artifact_id": art_id, "session_id": sessionId})
    return {"artifact": row}

def systemsthinking(system, components, relationships, feedbackLoops, emergentProperties, leveragePoints, sessionId, iteration, nextAnalysisNeeded, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0550000" if __import__("os").path.isdir("./environment_mix/0550000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate inputs (JSON-schema-like, additionalProperties already enforced by signature)
    if not isinstance(system, str) or not system:
        return _err("VALIDATION_ERROR", "system must be a non-empty string")
    if not isinstance(components, list) or any(not isinstance(x, str) for x in components):
        return _err("VALIDATION_ERROR", "components must be an array of strings")
    if not isinstance(relationships, list):
        return _err("VALIDATION_ERROR", "relationships must be an array")
    for i, r in enumerate(relationships):
        if not isinstance(r, dict):
            return _err("VALIDATION_ERROR", f"relationships[{i}] must be an object")
        for k in r.keys():
            if k not in ("from", "to", "type", "strength"):
                return _err("VALIDATION_ERROR", f"relationships[{i}] has unknown field '{k}'")
        if "from" not in r or "to" not in r or "type" not in r:
            return _err("VALIDATION_ERROR", f"relationships[{i}] must include from, to, type")
        if not isinstance(r["from"], str) or not isinstance(r["to"], str) or not isinstance(r["type"], str):
            return _err("VALIDATION_ERROR", f"relationships[{i}].from/to/type must be strings")
        if "strength" in r and r["strength"] is not None and not isinstance(r["strength"], (int, float)):
            return _err("VALIDATION_ERROR", f"relationships[{i}].strength must be a number when provided")
    if not isinstance(feedbackLoops, list):
        return _err("VALIDATION_ERROR", "feedbackLoops must be an array")
    for i, fl in enumerate(feedbackLoops):
