        if not isinstance(fl["components"], list) or any(not isinstance(x, str) for x in fl["components"]):
            return _err("VALIDATION_ERROR", f"feedbackLoops[{i}].components must be an array of strings")
        if fl["type"] not in ("positive", "negative"):
            return _err("VALIDATION_ERROR", f"feedbackLoops[{i}].type must be 'positive' or 'negative'")
        if not isinstance(fl["description"], str):
            return _err("VALIDATION_ERROR", f"feedbackLoops[{i}].description must be a string")
    if not isinstance(emergentProperties, list) or any(not isinstance(x, str) for x in emergentProperties):
