            "created_at": srow.get("created_at"),
            "updated_at": srow.get("updated_at"),
        },
        "meta": {
            "latency_ms": int((time.time() - start) * 1000),
            "timestamp": now,
        },
    }

def scientificmethod(stage, inquiryId, iteration, nextStageNeeded, observation=None, question=None, hypothesis=None, experiment=None, analysis=None, conclusion=None, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0550000" if __import__("os").path.isdir("./environment_mix/0550000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    allowed_stage = {"observation", "question", "hypothesis", "experiment", "analysis", "conclusion", "iteration"}
    if stage not in allowed_stage:
        return _err("VALIDATION_ERROR", "stage must be one of: observation, question, hypothesis, experiment, analysis, conclusion, iteration")
    if not isinstance(inquiryId, str) or not inquiryId or len(inquiryId) > 128:
        return _err("VALIDATION_ERROR", "inquiryId must be a non-empty string (1..128)")
    if not isinstance(iteration, (int, float)) or iteration < 0:
        return _err("VALIDATION_ERROR", "iteration must be a number >= 0")
    if not isinstance(nextStageNeeded, bool):
        return _err("VALIDATION_ERROR", "nextStageNeeded must be a boolean")

    if observation is not None and not isinstance(observation, str):
        return _err("VALIDATION_ERROR", "observation must be a string when provided")
    if question is not None and not isinstance(question, str):
        return _err("VALIDATION_ERROR", "question must be a string when provided")
    if analysis is not None and not isinstance(analysis, str):
        return _err("VALIDATION_ERROR", "analysis must be a string when provided")
    if conclusion is not None and not isinstance(conclusion, str):
        return _err("VALIDATION_ERROR", "conclusion must be a string when provided")

    # Hypothesis validation (if provided must satisfy schema + store constraints)
    hyp_status_order = {"proposed": 0, "testing": 1, "supported": 2, "refuted": 3, "refined": 99}
    if hypothesis is not None:
        if not isinstance(hypothesis, dict):
            return _err("VALIDATION_ERROR", "hypothesis must be an object when provided")
        allowed_hk = {"statement", "variables", "assumptions", "hypothesisId", "confidence", "domain", "iteration", "alternativeTo", "refinementOf", "status"}
        for k in hypothesis.keys():
            if k not in allowed_hk:
                return _err("VALIDATION_ERROR", f"hypothesis has unknown field '{k}'")
        required_hk = {"statement", "variables", "assumptions", "hypothesisId", "confidence", "domain", "iteration", "status"}
        missing = [k for k in required_hk if k not in hypothesis]
        if missing:
            return _err("VALIDATION_ERROR", f"hypothesis missing required fields: {', '.join(missing)}")
        if not isinstance(hypothesis["statement"], str):
            return _err("VALIDATION_ERROR", "hypothesis.statement must be a string")
        if not isinstance(hypothesis["variables"], list):
            return _err("VALIDATION_ERROR", "hypothesis.variables must be an array")
        var_types = {"independent", "dependent", "controlled", "confounding"}
        for i, v in enumerate(hypothesis["variables"]):
            if not isinstance(v, dict):
                return _err("VALIDATION_ERROR", f"hypothesis.variables[{i}] must be an object")
            for k in v.keys():
                if k not in ("name", "type", "operationalization"):
                    return _err("VALIDATION_ERROR", f"hypothesis.variables[{i}] has unknown field '{k}'")
            if "name" not in v or "type" not in v:
                return _err("VALIDATION_ERROR", f"hypothesis.variables[{i}] requires name and type")
            if not isinstance(v["name"], str):
                return _err("VALIDATION_ERROR", f"hypothesis.variables[{i}].name must be a string")
            if v["type"] not in var_types:
                return _err("VALIDATION_ERROR", f"hypothesis.variables[{i}].type invalid")
            if "operationalization" in v and v["operationalization"] is not None and not isinstance(v["operationalization"], str):
                return _err("VALIDATION_ERROR", f"hypothesis.variables[{i}].operationalization must be a string when provided")
        if not isinstance(hypothesis["assumptions"], list) or any(not isinstance(x, str) for x in hypothesis["assumptions"]):
            return _err("VALIDATION_ERROR", "hypothesis.assumptions must be an array of strings")
        if not isinstance(hypothesis["hypothesisId"], str) or not hypothesis["hypothesisId"]:
            return _err("VALIDATION_ERROR", "hypothesis.hypothesisId must be a non-empty string")
        if not isinstance(hypothesis["confidence"], (int, float)) or hypothesis["confidence"] < 0 or hypothesis["confidence"] > 1:
            return _err("VALIDATION_ERROR", "hypothesis.confidence must be a number in [0,1]")
        if not isinstance(hypothesis["domain"], str):
            return _err("VALIDATION_ERROR", "hypothesis.domain must be a string")
        if not isinstance(hypothesis["iteration"], (int, float)) or hypothesis["iteration"] < 0:
            return _err("VALIDATION_ERROR", "hypothesis.iteration must be a number >= 0")
        if hypothesis["status"] not in hyp_status_order:
            return _err("VALIDATION_ERROR", "hypothesis.status invalid")
        if "alternativeTo" in hypothesis and hypothesis["alternativeTo"] is not None:
            if not isinstance(hypothesis["alternativeTo"], list) or any(not isinstance(x, str) for x in hypothesis["alternativeTo"]):
                return _err("VALIDATION_ERROR", "hypothesis.alternativeTo must be an array of strings when provided")
        if "refinementOf" in hypothesis and hypothesis["refinementOf"] is not None and not isinstance(hypothesis["refinementOf"], str):
            return _err("VALIDATION_ERROR", "hypothesis.refinementOf must be a string when provided")

    # Experiment validation (if provided must satisfy schema + store constraints)
    if experiment is not None:
        if not isinstance(experiment, dict):
            return _err("VALIDATION_ERROR", "experiment must be an object when provided")
        allowed_ek = {"design", "methodology", "predictions", "experimentId", "hypothesisId", "controlMeasures", "results", "outcomeMatched", "unexpectedObservations", "limitations", "nextSteps"}
        for k in experiment.keys():
            if k not in allowed_ek:
                return _err("VALIDATION_ERROR", f"experiment has unknown field '{k}'")
        required_ek = {"design", "methodology", "predictions", "experimentId", "hypothesisId", "controlMeasures"}
        missing = [k for k in required_ek if k not in experiment]
        if missing:
            return _err("VALIDATION_ERROR", f"experiment missing required fields: {', '.join(missing)}")
        if not isinstance(experiment["design"], str):
            return _err("VALIDATION_ERROR", "experiment.design must be a string")
        if not isinstance(experiment["methodology"], str):
            return _err("VALIDATION_ERROR", "experiment.methodology must be a string")
        if not isinstance(experiment["predictions"], list):
            return _err("VALIDATION_ERROR", "experiment.predictions must be an array")
        for i, p in enumerate(experiment["predictions"]):
            if not isinstance(p, dict):
                return _err("VALIDATION_ERROR", f"experiment.predictions[{i}] must be an object")
            for k in p.keys():
                if k not in ("if", "then", "else"):
                    return _err("VALIDATION_ERROR", f"experiment.predictions[{i}] has unknown field '{k}'")
            if "if" not in p or "then" not in p:
                return _err("VALIDATION_ERROR", f"experiment.predictions[{i}] requires if and then")
            if not isinstance(p["if"], str) or not isinstance(p["then"], str):
                return _err("VALIDATION_ERROR", f"experiment.predictions[{i}].if/then must be strings")
            if "else" in p and p["else"] is not None and not isinstance(p["else"], str):
                return _err("VALIDATION_ERROR", f"experiment.predictions[{i}].else must be a string when provided")
        if not isinstance(experiment["experimentId"], str) or not experiment["experimentId"]:
            return _err("VALIDATION_ERROR", "experiment.experimentId must be a non-empty string")
        if not isinstance(experiment["hypothesisId"], str) or not experiment["hypothesisId"]:
            return _err("VALIDATION_ERROR", "experiment.hypothesisId must be a non-empty string")
        if not isinstance(experiment["controlMeasures"], list) or any(not isinstance(x, str) for x in experiment["controlMeasures"]):
            return _err("VALIDATION_ERROR", "experiment.controlMeasures must be an array of strings")
        if "results" in experiment and experiment["results"] is not None and not isinstance(experiment["results"], str):
            return _err("VALIDATION_ERROR", "experiment.results must be a string when provided")
        if "outcomeMatched" in experiment and experiment["outcomeMatched"] is not None and not isinstance(experiment["outcomeMatched"], bool):
            return _err("VALIDATION_ERROR", "experiment.outcomeMatched must be a boolean when provided")
        for arrk in ("unexpectedObservations", "limitations", "nextSteps"):
            if arrk in experiment and experiment[arrk] is not None:
                if not isinstance(experiment[arrk], list) or any(not isinstance(x, str) for x in experiment[arrk]):
                    return _err("VALIDATION_ERROR", f"experiment.{arrk} must be an array of strings when provided")

    # Ambient auth/context resolution: pick a usable active session (the most recently active) if one exists.
    sessions = _load("sessions.json")
    inquiries = _load("scientific_inquiries.json")

    # Resolve session: prefer the active session with latest activity, else latest created non-deleted.
    def _ts(v):
        if not v:
            return ""
        return v
    candidates = [s for s in sessions if s.get("status") != "deleted"]
    if not candidates:
        return _err("UNAUTHORIZED", "no available session context")
    candidates.sort(key=lambda s: (_ts(s.get("last_activity_at")), _ts(s.get("created_at")), s.get("id", "")), reverse=True)
    session = next((s for s in candidates if s.get("status") == "active"), None) or candidates[0]
    session_id = session.get("id")

    # Upsert by (session_id, external_inquiry_id) where status != deleted
    existing = next((r for r in inquiries if r.get("session_id") == session_id and r.get("external_inquiry_id") == inquiryId and r.get("status") != "deleted"), None)

    # Enforce hypothesis status monotonic transitions (stored inside hypothesis object)
    if existing and hypothesis is not None:
        prev_h = existing.get("hypothesis")
        if isinstance(prev_h, dict) and "status" in prev_h and prev_h["status"] in hyp_status_order:
            prev = prev_h["status"]
            new = hypothesis.get("status")
            if new in hyp_status_order:
                if new != "refined" and hyp_status_order[new] < hyp_status_order[prev]:
                    return _err("INVALID_TRANSITION", "hypothesis.status must be monotonic; only 'refined' may follow any prior status", previous=prev, attempted=new)

    # If experiment present and hypothesis present, can cross-check ids; if only one present accept.
    if experiment is not None and hypothesis is not None:
        if experiment.get("hypothesisId") != hypothesis.get("hypothesisId"):
            return _err("VALIDATION_ERROR", "experiment.hypothesisId must match hypothesis.hypothesisId when both are provided")

    if existing:
        # update in place
        existing["stage"] = stage
        existing["iteration"] = iteration
        existing["next_stage_needed"] = nextStageNeeded
        existing["observation"] = observation if observation is not None else existing.get("observation")
        existing["question"] = question if question is not None else existing.get("question")
        existing["analysis"] = analysis if analysis is not None else existing.get("analysis")
        existing["conclusion"] = conclusion if conclusion is not None else existing.get("conclusion")
        if hypothesis is not None:
            existing["hypothesis"] = hypothesis
        if experiment is not None:
            existing["experiment"] = experiment
        existing["updated_at"] = now
        row = existing
        created = False
    else:
        iid = "inq_" + uuid.uuid4().hex
        row = {
            "id": iid,
            "session_id": session_id,
            "external_inquiry_id": inquiryId,
            "status": "active",
            "stage": stage,
            "observation": observation,
            "question": question,
            "analysis": analysis,
            "conclusion": conclusion,
            "iteration": iteration,
            "next_stage_needed": nextStageNeeded,
            "hypothesis": hypothesis,
            "experiment": experiment,
            "created_at": now,
            "updated_at": now,
        }
        inquiries.append(row)
        created = True

    # Update session last_activity_at (and counters if created)
    session["last_activity_at"] = now
    if "updated_at" in session:
        session["updated_at"] = now
    else:
        session["updated_at"] = now
    if created:
        session["total_artifacts"] = int(session.get("total_artifacts") or 0)  # unchanged
        session["total_thoughts"] = int(session.get("total_thoughts") or 0)
        session["total_branches"] = int(session.get("total_branches") or 0)

    _save("scientific_inquiries.json", inquiries)
    _save("sessions.json", sessions)

    return {
        "scientific_inquiry": row,
        "context": {"session_id": session_id},
        "meta": {
            "created": created,
            "latency_ms": int((time.time() - start) * 1000),
            "timestamp": now,
        },
    }

def structuredargumentation(claim, premises, conclusion, argumentType, confidence, nextArgumentNeeded, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0550000" if __import__("os").path.isdir("./environment_mix/0550000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if not isinstance(claim, str) or not claim:
        return _err("VALIDATION_ERROR", "claim must be a non-empty string")
    if not isinstance(premises, list) or any(not isinstance(x, str) for x in premises):
        return _err("VALIDATION_ERROR", "premises must be an array of strings")
    if not isinstance(conclusion, str) or not conclusion:
        return _err("VALIDATION_ERROR", "conclusion must be a non-empty string")
    if not isinstance(argumentType, str) or not argumentType:
        return _err("VALIDATION_ERROR", "argumentType must be a non-empty string")
    if not isinstance(confidence, (int, float)):
        return _err("VALIDATION_ERROR", "confidence must be a number")
    if not isinstance(nextArgumentNeeded, bool):
        return _err("VALIDATION_ERROR", "nextArgumentNeeded must be a boolean")

    sessions = _load("sessions.json")
    artifacts = _load("artifacts.json")

    # Ambient context: choose an active session if any; else any non-deleted.
    candidates = [s for s in sessions if s.get("status") != "deleted"]
    if not candidates:
        return _err("UNAUTHORIZED", "no available session context")
    candidates.sort(key=lambda s: (s.get("last_activity_at") or "", s.get("created_at") or "", s.get("id") or ""), reverse=True)
    srow = next((s for s in candidates if s.get("status") == "active"), None) or candidates[0]
    sessionId = srow.get("id")

    payload = {
        "claim": claim,
        "premises": premises,
        "conclusion": conclusion,
        "argumentType": argumentType,
        "confidence": confidence,
        "nextArgumentNeeded": nextArgumentNeeded,
    }

    aid = "art_" + uuid.uuid4().hex
    arow = {
        "id": aid,
        "session_id": sessionId,
        "status": "active",
        "tool_name": "structuredargumentation",
        "external_object_id": None,
        "iteration": None,
        "stage": None,
        "next_needed": nextArgumentNeeded,
        "payload": payload,
        "created_at": now,
        "updated_at": now,
    }
    artifacts.append(arow)

    srow["last_activity_at"] = now
    srow["total_artifacts"] = int(srow.get("total_artifacts") or 0) + 1
    srow["updated_at"] = now

    _save("artifacts.json", artifacts)
    _save("sessions.json", sessions)

    # Return evaluation (non-fabricated fields limited; evaluation derived)
    evaluation = {
        "argumentType": argumentType,
        "premise_count": len(premises),
        "confidence": float(confidence),
        "nextArgumentNeeded": nextArgumentNeeded,
        "notes": "Stored argument payload as an artifact.",
    }

    return {
        "artifact": arow,
        "evaluation": evaluation,
        "context": {"session_id": sessionId},
        "meta": {"latency_ms": int((time.time() - start) * 1000), "timestamp": now},
    }

def visualreasoning(operation, diagramId, diagramType, iteration, nextOperationNeeded, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0550000" if __import__("os").path.isdir("./environment_mix/0550000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_request_log(status, error_code=None, error_message=None, meta=None):
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "visualreasoning",
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": latency_ms,
            "timestamp": now,
        }
        if isinstance(meta, dict):
            row["meta"] = meta
        for fname in ("request_logs.json", "requests.json", "usage.json", "audit_logs.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                data = _load(fname)
                if isinstance(data, list):
                    data.append(row)
                    _save(fname, data)
                elif isinstance(data, dict) and isinstance(data.get("requests"), list):
                    data["requests"].append(row)
                    _save(fname, data)
                break

    def _rate_limit_check():
        cfg = _load("rate_limits.json")
        if not isinstance(cfg, dict):
            cfg = {}
        rate = cfg.get("rate_limit_per_minute")
        quota = cfg.get("daily_quota")
        if rate is None and quota is None:
            return None

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
        minute_ago = now_dt - datetime.timedelta(seconds=60)
        day_ago = now_dt - datetime.timedelta(days=1)

        def _parse_ts(s):
            if not isinstance(s, str):
                return None
            try:
                return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            except Exception:
                return None

        count_min = 0
        count_day = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != "visualreasoning":
                continue
            ts = _parse_ts(r.get("timestamp"))
            if not ts:
                continue
            if ts >= minute_ago:
                count_min += 1
            if ts >= day_ago:
                count_day += 1

        if isinstance(rate, int) and rate >= 0 and count_min >= rate:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        if isinstance(quota, int) and quota >= 0 and count_day >= quota:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    rl = _rate_limit_check()
    if rl:
        _append_request_log("error", rl["error"]["code"], rl["error"]["message"])
        return rl

    # Validate inputs (relax operation: it's a string, not necessarily one of enums)
    if not isinstance(operation, str):
        _append_request_log("error", "VALIDATION_ERROR", "operation must be a string")
        return _err("VALIDATION_ERROR", "operation must be a string")
    if not isinstance(diagramId, str) or not (1 <= len(diagramId) <= 128):
        _append_request_log("error", "VALIDATION_ERROR", "diagramId must be a non-empty string (1..128)")
        return _err("VALIDATION_ERROR", "diagramId must be a non-empty string (1..128)")
    if not isinstance(diagramType, str) or not diagramType:
        _append_request_log("error", "VALIDATION_ERROR", "diagramType must be a non-empty string")
        return _err("VALIDATION_ERROR", "diagramType must be a non-empty string")
    if not isinstance(iteration, (int, float)) or isinstance(iteration, bool):
        _append_request_log("error", "VALIDATION_ERROR", "iteration must be a number")
        return _err("VALIDATION_ERROR", "iteration must be a number")
    if iteration < 0:
        _append_request_log("error", "VALIDATION_ERROR", "iteration must be >= 0")
        return _err("VALIDATION_ERROR", "iteration must be >= 0")
    if not isinstance(nextOperationNeeded, bool):
        _append_request_log("error", "VALIDATION_ERROR", "nextOperationNeeded must be a boolean")
        return _err("VALIDATION_ERROR", "nextOperationNeeded must be a boolean")

    sessions = _load("sessions.json")
    if not isinstance(sessions, list):
        sessions = []

    # Visual reasoning must be attached to an existing session; the tool surface doesn't provide sessionId.
    # Resolve a usable session context by finding (a) a non-deleted session, and (b) preferably one that already
    # has this diagramId for visualreasoning artifact; if none exists, fall back to any active session.
    artifacts = _load("artifacts.json")
    if not isinstance(artifacts, list):
        artifacts = []

    existing = None
    for a in artifacts:
        if not isinstance(a, dict):
            continue
        if a.get("status") == "deleted":
            continue
        if a.get("tool_name") != "visualreasoning":
            continue
        if a.get("external_object_id") == diagramId:
            existing = a
            break

    session_row = None
    if existing:
        sid = existing.get("session_id")
        session_row = next((s for s in sessions if isinstance(s, dict) and s.get("id") == sid and s.get("status") != "deleted"), None)

    if not session_row:
        # choose any active session if present, else any non-deleted session
        active = [s for s in sessions if isinstance(s, dict) and s.get("status") == "active"]
        non_deleted = [s for s in sessions if isinstance(s, dict) and s.get("status") != "deleted"]
        session_row = (active[0] if active else (non_deleted[0] if non_deleted else None))

    if not session_row:
        _append_request_log("error", "UNAUTHORIZED", "no available session context")
        return _err("UNAUTHORIZED", "no available session context")

    sessionId = session_row.get("id")

    payload = {
        "operation": operation,
        "diagramId": diagramId,
        "diagramType": diagramType,
        "iteration": iteration,
        "nextOperationNeeded": nextOperationNeeded,
    }

    # external_object_id required and must match payload.diagramId
    external_object_id = diagramId
    if payload.get("diagramId") != external_object_id:
        _append_request_log("error", "VALIDATION_ERROR", "payload.diagramId must match external_object_id")
        return _err("VALIDATION_ERROR", "payload.diagramId must match external_object_id")

    # Upsert by (session_id, tool_name, external_object_id) where status != 'deleted'
    target = next(
        (a for a in artifacts
         if isinstance(a, dict)
         and a.get("status") != "deleted"
         and a.get("session_id") == sessionId
         and a.get("tool_name") == "visualreasoning"
         and a.get("external_object_id") == external_object_id),
        None
    )

    if target:
        # Update existing artifact; do not enforce "diagram must already exist in session" beyond natural key lookup.
        target["payload"] = payload
        target["iteration"] = iteration
        target["next_needed"] = nextOperationNeeded
        target["updated_at"] = now
        saved = target
        created_new = False
    else:
        # If the diagram exists in some other session, keep using that session instead of failing.
        if existing and (existing.get("session_id") != sessionId):
            sessionId2 = existing.get("session_id")
            s2 = next((s for s in sessions if isinstance(s, dict) and s.get("id") == sessionId2 and s.get("status") != "deleted"), None)
            if s2:
                session_row = s2
                sessionId = sessionId2
                target2 = next(
                    (a for a in artifacts
                     if isinstance(a, dict)
                     and a.get("status") != "deleted"
                     and a.get("session_id") == sessionId
                     and a.get("tool_name") == "visualreasoning"
                     and a.get("external_object_id") == external_object_id),
                    None
                )
                if target2:
                    target2["payload"] = payload
                    target2["iteration"] = iteration
                    target2["next_needed"] = nextOperationNeeded
                    target2["updated_at"] = now
                    saved = target2
                    created_new = False
                else:
                    # create in that session
                    art_id = "ct_art_" + uuid.uuid4().hex[:26]
                    saved = {
                        "id": art_id,
                        "session_id": sessionId,
                        "status": "active",
                        "tool_name": "visualreasoning",
                        "external_object_id": external_object_id,
                        "iteration": iteration,
                        "stage": None,
                        "next_needed": nextOperationNeeded,
                        "payload": payload,
                        "created_at": now,
                        "updated_at": now,
                    }
                    artifacts.append(saved)
                    created_new = True
            else:
                existing = None  # fall through to create new in resolved session

        if not existing:
            # Create new artifact in resolved session
            art_id = "ct_art_" + uuid.uuid4().hex[:26]
            saved = {
                "id": art_id,
                "session_id": sessionId,
                "status": "active",
                "tool_name": "visualreasoning",
                "external_object_id": external_object_id,
                "iteration": iteration,
                "stage": None,
                "next_needed": nextOperationNeeded,
                "payload": payload,
                "created_at": now,
                "updated_at": now,
            }
            artifacts.append(saved)
            created_new = True

    _save("artifacts.json", artifacts)

    # Update session activity + cached counters
    session_row["last_activity_at"] = now
    session_row["updated_at"] = now
    if created_new:
        if not isinstance(session_row.get("total_artifacts"), int) or session_row.get("total_artifacts") < 0:
            session_row["total_artifacts"] = sum(
                1 for a in artifacts
                if isinstance(a, dict) and a.get("session_id") == sessionId and a.get("status") != "deleted"
            )
        else:
            session_row["total_artifacts"] += 1
    _save("sessions.json", sessions)

    _append_request_log("success", meta={"artifact_id": saved.get("id"), "session_id": sessionId, "diagram_id": diagramId})
    return {"artifact": saved}

def session_info(sessionId=None, clientSessionKey=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0550000" if __import__("os").path.isdir("./environment_mix/0550000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Request logging + quota/rate-limit scaffolding (best-effort; schema not provided)
    def _log(status, credential=None, extra=None):
        logs = _load("request_logs.json")
        row = {
            "id": f"ct_req_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": "session_info",
            "credential": credential,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now
        }
        if extra:
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)

    # Validate inputs
    if sessionId is not None:
        if not isinstance(sessionId, str):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "sessionId must be a string")
        if not re.match(r"^ct_sess_[0-9A-HJKMNP-TV-Z]{10,}$", sessionId):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "sessionId does not match required ct_sess_… ULID pattern")
    if clientSessionKey is not None and not isinstance(clientSessionKey, str):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "clientSessionKey must be a string")

    sessions = _load("sessions.json")
    thoughts = _load("thoughts.json")
    artifacts = _load("artifacts.json")
    collab_sessions = _load("collaboration_sessions.json")
    sci = _load("scientific_inquiries.json")

    # Resolve target session
    sess = None
    if sessionId:
        for s in sessions:
            if s.get("id") == sessionId:
                sess = s
                break
        if sess is None:
            _log("NOT_FOUND")
            return _err("NOT_FOUND", "Session not found", sessionId=sessionId)
    elif clientSessionKey:
        for s in sessions:
            if s.get("client_session_key") == clientSessionKey:
                sess = s
                break
        if sess is None:
            _log("NOT_FOUND")
            return _err("NOT_FOUND", "Session not found", clientSessionKey=clientSessionKey)
    else:
        # No selector provided; must not guess. Behave as validation error.
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Must provide sessionId or clientSessionKey")

    if sess.get("status") == "deleted":
        # still exists but considered not accessible via surface
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "Session not found")

    sid = sess.get("id")

    def _ts(v):
        # parse ISO-like; treat None as minimal
        if not v:
            return None
        try:
            if isinstance(v, str) and v.endswith("Z"):
                v2 = v[:-1]
            else:
                v2 = v
            return datetime.datetime.fromisoformat(v2)
        except Exception:
            return None

    # Recent activity across newest thoughts/artifacts/collaboration_sessions/scientific_inquiries by created_at desc
    activity = []

    for t in thoughts:
        if t.get("session_id") == sid and t.get("status") != "deleted":
            created = t.get("created_at")
            activity.append({
                "type": "thought",
                "id": t.get("id"),
                "created_at": created,
                "status": t.get("status"),
                "thought_number": t.get("thought_number"),
                "branch_id": t.get("branch_id"),
                "preview": (t.get("thought") or "")[:200]
            })
    for a in artifacts:
        if a.get("session_id") == sid and a.get("status") != "deleted":
            created = a.get("created_at")
            activity.append({
                "type": "artifact",
                "id": a.get("id"),
                "created_at": created,
                "status": a.get("status"),
                "tool_name": a.get("tool_name"),
                "external_object_id": a.get("external_object_id"),
                "stage": a.get("stage"),
                "iteration": a.get("iteration"),
                "next_needed": a.get("next_needed")
            })
    for cs in collab_sessions:
        if cs.get("session_id") == sid and cs.get("status") != "deleted":
            created = cs.get("created_at")
            activity.append({
                "type": "collaboration_session",
                "id": cs.get("id"),
                "created_at": created,
                "status": cs.get("status"),
                "external_session_id": cs.get("external_session_id"),
                "topic": cs.get("topic"),
                "stage": cs.get("stage"),
                "iteration": cs.get("iteration"),
                "next_contribution_needed": cs.get("next_contribution_needed")
            })
    for iq in sci:
        if iq.get("session_id") == sid and iq.get("status") != "deleted":
            created = iq.get("created_at")
            activity.append({
                "type": "scientific_inquiry",
                "id": iq.get("id"),
                "created_at": created,
                "status": iq.get("status"),
                "external_inquiry_id": iq.get("external_inquiry_id"),
                "stage": iq.get("stage"),
                "iteration": iq.get("iteration"),
                "next_stage_needed": iq.get("next_stage_needed"),
                "preview": ((iq.get("question") or iq.get("observation") or iq.get("analysis") or "")[:200])
            })

    def _sort_key(x):
        dt = _ts(x.get("created_at"))
        if dt is None:
            return datetime.datetime(1970, 1, 1)
        return dt

    activity.sort(key=_sort_key, reverse=True)
    recent_activity = activity[:20]

    body = {
        "session": {
            "id": sess.get("id"),
            "status": sess.get("status"),
            "title": sess.get("title"),
            "clientSessionKey": sess.get("client_session_key"),
            "createdAt": sess.get("created_at"),
            "updatedAt": sess.get("updated_at"),
            "lastActivityAt": sess.get("last_activity_at"),
            "totals": {
                "artifacts": sess.get("total_artifacts", 0),
                "thoughts": sess.get("total_thoughts", 0),
                "branches": sess.get("total_branches", 0)
            }
        },
        "recentActivity": recent_activity
    }

    _log("OK")
    return body

def session_export(format=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0550000" if __import__("os").path.isdir("./environment_mix/0550000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, credential=None, extra=None):
        logs = _load("request_logs.json")
        row = {
            "id": f"ct_req_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": "session_export",
            "credential": credential,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now
        }
        if extra:
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)

    if format is None:
        format = "json"
    if not isinstance(format, str):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "format must be a string")
    if format not in ("json", "summary"):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unsupported format", supported=["json", "summary"])

    # Ambient auth: pick a session that exists and is not deleted.
    sessions = _load("sessions.json")
    if not sessions:
        _log("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No accessible sessions")
    sess = None
    for s in sessions:
        if s.get("status") != "deleted":
            sess = s
            break
    if sess is None:
        _log("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No accessible sessions")

    # Consistent snapshot: single-read of each collection into memory before constructing output.
    sid = sess.get("id")
    thoughts = _load("thoughts.json")
    artifacts = _load("artifacts.json")
    collab_sessions = _load("collaboration_sessions.json")
    collab_entities = _load("collaboration_entities.json")
    sci = _load("scientific_inquiries.json")

    def _not_deleted(row, status_field="status"):
        v = row.get(status_field)
        return v is None or v != "deleted"

    snap_thoughts = [t for t in thoughts if t.get("session_id") == sid and _not_deleted(t, "status")]
    snap_artifacts = [a for a in artifacts if a.get("session_id") == sid and _not_deleted(a, "status")]
    snap_collab_sessions = [cs for cs in collab_sessions if cs.get("session_id") == sid and _not_deleted(cs, "status")]
    collab_session_ids = set(cs.get("id") for cs in snap_collab_sessions if cs.get("id"))
    snap_collab_entities = [ce for ce in collab_entities if ce.get("collaboration_session_id") in collab_session_ids]
    snap_sci = [iq for iq in sci if iq.get("session_id") == sid and _not_deleted(iq, "status")]

    if format == "json":
        export_payload = {
            "exportVersion": 1,
            "exportedAt": now,
            "session": sess,
            "thoughts": snap_thoughts,
            "artifacts": snap_artifacts,
            "collaboration_sessions": snap_collab_sessions,
            "collaboration_entities": snap_collab_entities,
            "scientific_inquiries": snap_sci
        }
        _log("OK")
        return {"format": "json", "data": export_payload}

    # summary format: no full payload blobs; include counts and recent titles/previews
    def _preview(s):
        if s is None:
            return None
        if not isinstance(s, str):
            s = str(s)
        return s[:200]

    def _ts(v):
        if not v:
            return None
        try:
            if isinstance(v, str) and v.endswith("Z"):
                v = v[:-1]
            return datetime.datetime.fromisoformat(v)
        except Exception:
            return None

    recent_thoughts = sorted(snap_thoughts, key=lambda r: _ts(r.get("created_at")) or datetime.datetime(1970, 1, 1), reverse=True)[:5]
    recent_artifacts = sorted(snap_artifacts, key=lambda r: _ts(r.get("created_at")) or datetime.datetime(1970, 1, 1), reverse=True)[:5]
    recent_collab = sorted(snap_collab_sessions, key=lambda r: _ts(r.get("created_at")) or datetime.datetime(1970, 1, 1), reverse=True)[:5]
    recent_sci = sorted(snap_sci, key=lambda r: _ts(r.get("created_at")) or datetime.datetime(1970, 1, 1), reverse=True)[:5]

    export_payload = {
        "exportVersion": 1,
        "exportedAt": now,
        "session": {
            "id": sess.get("id"),
            "status": sess.get("status"),
            "title": sess.get("title"),
            "clientSessionKey": sess.get("client_session_key"),
            "createdAt": sess.get("created_at"),
            "updatedAt": sess.get("updated_at"),
            "lastActivityAt": sess.get("last_activity_at"),
            "totals": {
                "artifacts": sess.get("total_artifacts", 0),
                "thoughts": sess.get("total_thoughts", 0),
                "branches": sess.get("total_branches", 0)
            }
        },
        "counts": {
            "thoughts": len(snap_thoughts),
            "artifacts": len(snap_artifacts),
            "collaboration_sessions": len(snap_collab_sessions),
            "collaboration_entities": len(snap_collab_entities),
            "scientific_inquiries": len(snap_sci)
        },
        "recent": {
            "thoughts": [{
                "id": t.get("id"),
                "created_at": t.get("created_at"),
                "thought_number": t.get("thought_number"),
                "branch_id": t.get("branch_id"),
                "preview": _preview(t.get("thought"))
            } for t in recent_thoughts],
            "artifacts": [{
                "id": a.get("id"),
                "created_at": a.get("created_at"),
                "tool_name": a.get("tool_name"),
                "external_object_id": a.get("external_object_id"),
                "stage": a.get("stage"),
                "iteration": a.get("iteration"),
                "next_needed": a.get("next_needed")
            } for a in recent_artifacts],
            "collaboration_sessions": [{
                "id": cs.get("id"),
                "created_at": cs.get("created_at"),
                "external_session_id": cs.get("external_session_id"),
                "topic": _preview(cs.get("topic")),
                "stage": cs.get("stage"),
                "iteration": cs.get("iteration")
            } for cs in recent_collab],
            "scientific_inquiries": [{
                "id": iq.get("id"),
                "created_at": iq.get("created_at"),
                "external_inquiry_id": iq.get("external_inquiry_id"),
                "stage": iq.get("stage"),
                "preview": _preview(iq.get("question") or iq.get("observation") or iq.get("analysis") or iq.get("conclusion"))
            } for iq in recent_sci]
        }
    }

    _log("OK")
    return {"format": "summary", "data": export_payload}

def session_import(sessionData, merge=None, **_extra):
    import json, os, datetime, time, uuid, copy

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0550000" if __import__("os").path.isdir("./environment_mix/0550000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_request_log(status, error_code=None, error_message=None, meta=None):
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "session_import",
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": latency_ms,
            "timestamp": now,
        }
        if isinstance(meta, dict):
            row["meta"] = meta
        for fname in ("request_logs.json", "requests.json", "usage.json", "audit_logs.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                data = _load(fname)
                if isinstance(data, list):
                    data.append(row)
                    _save(fname, data)
                elif isinstance(data, dict) and isinstance(data.get("requests"), list):
                    data["requests"].append(row)
                    _save(fname, data)
                break

    if merge is None:
        merge = False
    if not isinstance(sessionData, str):
        _append_request_log("error", "VALIDATION_ERROR", "sessionData must be a string")
        return _err("VALIDATION_ERROR", "sessionData must be a string")
    if not isinstance(merge, bool):
        _append_request_log("error", "VALIDATION_ERROR", "merge must be a boolean")
        return _err("VALIDATION_ERROR", "merge must be a boolean")

    # Accept either a JSON export string OR a plain session id string (treat as a minimal export reference).
    payload = None
    try:
        payload = json.loads(sessionData)
    except Exception:
        payload = None

    sessions = _load("sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    thoughts = _load("thoughts.json")
    if not isinstance(thoughts, list):
        thoughts = []
    artifacts = _load("artifacts.json")
    if not isinstance(artifacts, list):
        artifacts = []
    col_sessions = _load("collaboration_sessions.json")
    if not isinstance(col_sessions, list):
        col_sessions = []
    col_entities = _load("collaboration_entities.json")
    if not isinstance(col_entities, list):
        col_entities = []
    sci = _load("scientific_inquiries.json")
    if not isinstance(sci, list):
        sci = []

    def _gen_id(prefix):
        return prefix + "_" + uuid.uuid4().hex[:26]

    def _is_deleted_status(v):
        return v == "deleted"

    def _recompute_session_caches(sess_id):
        ta = sum(1 for a in artifacts if isinstance(a, dict) and a.get("session_id") == sess_id and a.get("status") != "deleted")
        th_active = [t for t in thoughts if isinstance(t, dict) and t.get("session_id") == sess_id and t.get("status") != "deleted"]
        tt = len(th_active)
        branches = set()
        for t in th_active:
            bid = t.get("branch_id")
            if bid is not None:
                branches.add(bid)
        tb = len(branches)
        return ta, tt, tb

    # If not JSON, interpret as "import session by id reference" (minimal, valid per tool surface)
    if payload is None:
        sid = sessionData.strip()
        srow = next((s for s in sessions if isinstance(s, dict) and s.get("id") == sid), None)
        if not srow:
            _append_request_log("error", "VALIDATION_ERROR", "sessionData is not valid JSON and is not a known session id")
            return _err("VALIDATION_ERROR", "sessionData is not valid JSON and is not a known session id")
        # Return current session state (not a mutation, but tool semantics are import; treat as no-op merge)
        out = {
            "session": srow,
            "thoughts": [t for t in thoughts if isinstance(t, dict) and t.get("session_id") == sid and t.get("status") != "deleted"],
            "artifacts": [a for a in artifacts if isinstance(a, dict) and a.get("session_id") == sid and a.get("status") != "deleted"],
            "collaboration_sessions": [c for c in col_sessions if isinstance(c, dict) and c.get("session_id") == sid and c.get("status") != "deleted"],
            "collaboration_entities": [],
            "scientific_inquiries": [q for q in sci if isinstance(q, dict) and q.get("session_id") == sid and q.get("status") != "deleted"],
        }
        # add collab entities for those collab sessions
        col_ids = set(c.get("id") for c in out["collaboration_sessions"] if isinstance(c, dict))
        out["collaboration_entities"] = [e for e in col_entities if isinstance(e, dict) and e.get("collaboration_session_id") in col_ids]
        _append_request_log("success", meta={"mode": "reference_noop", "session_id": sid})
        return out

    # Validate export object
    if not isinstance(payload, dict):
        _append_request_log("error", "VALIDATION_ERROR", "Export payload must be a JSON object")
        return _err("VALIDATION_ERROR", "Export payload must be a JSON object")
    if "session" not in payload or not isinstance(payload.get("session"), dict):
        _append_request_log("error", "VALIDATION_ERROR", "Export payload missing session object")
        return _err("VALIDATION_ERROR", "Export payload missing session object")

    in_session = payload.get("session", {})
    in_thoughts = payload.get("thoughts", [])
    in_artifacts = payload.get("artifacts", [])
    in_collab_sessions = payload.get("collaboration_sessions", [])
    in_collab_entities = payload.get("collaboration_entities", [])
    in_sci = payload.get("scientific_inquiries", [])

    for k, v in (
        ("thoughts", in_thoughts),
        ("artifacts", in_artifacts),
        ("collaboration_sessions", in_collab_sessions),
        ("collaboration_entities", in_collab_entities),
        ("scientific_inquiries", in_sci),
    ):
        if v is None:
            continue
        if not isinstance(v, list):
            _append_request_log("error", "VALIDATION_ERROR", f"{k} must be an array when present")
            return _err("VALIDATION_ERROR", f"{k} must be an array when present")

    # Resolve target session for merge/upsert
    client_key = in_session.get("client_session_key")
    exported_id = in_session.get("id")

    target_session = None
    if merge:
        if isinstance(client_key, str) and client_key:
            target_session = next((s for s in sessions if isinstance(s, dict) and s.get("client_session_key") == client_key and s.get("status") != "deleted"), None)
        if not target_session and isinstance(exported_id, str) and exported_id:
            target_session = next((s for s in sessions if isinstance(s, dict) and s.get("id") == exported_id and s.get("status") != "deleted"), None)

    if (not merge) and target_session:
        _append_request_log("error", "CONFLICT", "merge=false would overwrite an existing session", session_id=target_session.get("id") if isinstance(target_session, dict) else None)
        return _err("CONFLICT", "merge=false would overwrite an existing session")

    # Create or update session
    created_new_session = False
    if not target_session:
        # Create a new session always when not merging, or when merging but no match found.
        new_id = _gen_id("ct_sess")
        created_new_session = True
        target_session = {
            "id": new_id,
            "status": (in_session.get("status") if in_session.get("status") in ("active", "archived", "deleted") else "active"),
            "title": in_session.get("title"),
            "client_session_key": client_key if isinstance(client_key, str) and client_key else None,
            "last_activity_at": None,
            "total_artifacts": 0,
            "total_thoughts": 0,
            "total_branches": 0,
            "created_at": now,
            "updated_at": now,
        }
        # uniqueness(client_session_key) where not null
        if target_session["client_session_key"] is not None:
            if any(isinstance(s, dict) and s.get("client_session_key") == target_session["client_session_key"] for s in sessions):
                _append_request_log("error", "CONFLICT", "client_session_key already exists")
                return _err("CONFLICT", "client_session_key already exists")
        sessions.append(target_session)
    else:
        # Update mutable fields if provided
        if isinstance(in_session.get("title"), str):
            target_session["title"] = in_session.get("title")
        if in_session.get("status") in ("active", "archived", "deleted"):
            target_session["status"] = in_session.get("status")
        if isinstance(client_key, str) and client_key:
            # enforce unique if changing
            if target_session.get("client_session_key") != client_key:
                if any(isinstance(s, dict) and s.get("client_session_key") == client_key and s.get("id") != target_session.get("id") for s in sessions):
                    _append_request_log("error", "CONFLICT", "client_session_key already exists")
                    return _err("CONFLICT", "client_session_key already exists")
            target_session["client_session_key"] = client_key
        target_session["updated_at"] = now

    target_session_id = target_session.get("id")

    # Map exported session_id -> target internal id for children
    def _sid_of(child):
        sid = child.get("session_id")
        if sid == exported_id or sid is None:
            return target_session_id
        # If export stored already-mapped session_id equal to exported id, use target id; else force to target anyway.
        return target_session_id

    # Upsert children
    # Thoughts by (session_id, branch_id, thought_number) where status != deleted
    if isinstance(in_thoughts, list):
        for it in in_thoughts:
            if not isinstance(it, dict):
                continue
            if _is_deleted_status(it.get("status")):
                continue
            b = it.get("branch_id")
            tn = it.get("thought_number")
            if not isinstance(tn, (int, float)) or isinstance(tn, bool) or tn < 1:
                continue  # skip invalid rows rather than failing whole import
            sid = _sid_of(it)
            existing = next(
                (t for t in thoughts if isinstance(t, dict) and t.get("session_id") == sid and t.get("status") != "deleted" and t.get("branch_id") == b and t.get("thought_number") == tn),
                None
            )
            if existing and merge:
                existing["thought"] = it.get("thought", existing.get("thought"))
                existing["total_thoughts"] = it.get("total_thoughts", existing.get("total_thoughts"))
                existing["next_thought_needed"] = it.get("next_thought_needed", existing.get("next_thought_needed"))
                existing["needs_more_thoughts"] = it.get("needs_more_thoughts", existing.get("needs_more_thoughts"))
                existing["branch_from_thought_number"] = it.get("branch_from_thought_number", existing.get("branch_from_thought_number"))
                existing["is_revision"] = it.get("is_revision", existing.get("is_revision"))
                existing["revises_thought_number"] = it.get("revises_thought_number", existing.get("revises_thought_number"))
                existing["updated_at"] = now
            else:
                new_t = copy.deepcopy(it)
                new_t["id"] = _gen_id("ct_tht")
                new_t["session_id"] = sid
                new_t["status"] = "active" if it.get("status") not in ("superseded", "deleted") else it.get("status")
                new_t["created_at"] = now
                new_t["updated_at"] = now
                # Do not import supersedes_thought_id blindly; it's internal linkage.
                if "supersedes_thought_id" in new_t:
                    new_t["supersedes_thought_id"] = None
                thoughts.append(new_t)

    # Artifacts by (session_id, tool_name, external_object_id) when external_object_id not null; else always create new
    if isinstance(in_artifacts, list):
        for it in in_artifacts:
            if not isinstance(it, dict):
                continue
            if _is_deleted_status(it.get("status")):
                continue
            sid = _sid_of(it)
            tool = it.get("tool_name")
            ext = it.get("external_object_id")
            if tool is None:
                continue
            if ext is not None and merge:
                existing = next(
                    (a for a in artifacts if isinstance(a, dict) and a.get("session_id") == sid and a.get("status") != "deleted" and a.get("tool_name") == tool and a.get("external_object_id") == ext),
                    None
                )
                if existing:
                    if isinstance(it.get("payload"), dict):
                        existing["payload"] = it.get("payload")
                    existing["iteration"] = it.get("iteration", existing.get("iteration"))
                    existing["stage"] = it.get("stage", existing.get("stage"))
                    existing["next_needed"] = it.get("next_needed", existing.get("next_needed"))
                    existing["updated_at"] = now
                    continue
            # create new
            new_a = copy.deepcopy(it)
            new_a["id"] = _gen_id("ct_art")
            new_a["session_id"] = sid
            new_a["status"] = it.get("status") if it.get("status") in ("active", "finalized") else "active"
            new_a["created_at"] = now
            new_a["updated_at"] = now
            artifacts.append(new_a)

    # Collaboration sessions by external_session_id
    ext_to_new_col = {}  # mapping of exported collab session internal id -> new id
    if isinstance(in_collab_sessions, list):
        for it in in_collab_sessions:
            if not isinstance(it, dict):
                continue
            if it.get("status") == "deleted":
                continue
            sid = _sid_of(it)
            ext_sid = it.get("external_session_id")
            if not isinstance(ext_sid, str) or not (1 <= len(ext_sid) <= 128):
                continue
            existing = None
            if merge:
                existing = next(
                    (c for c in col_sessions if isinstance(c, dict) and c.get("session_id") == sid and c.get("status") != "deleted" and c.get("external_session_id") == ext_sid),
                    None
                )
            if existing:
                existing["topic"] = it.get("topic", existing.get("topic"))
                existing["stage"] = it.get("stage", existing.get("stage"))
                existing["active_persona_id"] = it.get("active_persona_id", existing.get("active_persona_id"))
                existing["iteration"] = it.get("iteration", existing.get("iteration"))
                existing["next_contribution_needed"] = it.get("next_contribution_needed", existing.get("next_contribution_needed"))
                existing["updated_at"] = now
                if isinstance(it.get("id"), str):
                    ext_to_new_col[it["id"]] = existing.get("id")
            else:
                new_c = copy.deepcopy(it)
                old_id = new_c.get("id")
                new_id = _gen_id("ct_col")
                new_c["id"] = new_id
                new_c["session_id"] = sid
                new_c["status"] = it.get("status") if it.get("status") in ("active", "completed") else "active"
                new_c["created_at"] = now
                new_c["updated_at"] = now
                col_sessions.append(new_c)
                if isinstance(old_id, str):
                    ext_to_new_col[old_id] = new_id

    # Collaboration entities: remap collaboration_session_id and just copy rows (upsert persona uniqueness if merge)
    if isinstance(in_collab_entities, list):
        for it in in_collab_entities:
            if not isinstance(it, dict):
                continue
            old_parent = it.get("collaboration_session_id")
            parent = ext_to_new_col.get(old_parent, old_parent)
            if not isinstance(parent, str) or not parent:
                continue
            ent_type = it.get("entity_type")
            if ent_type not in ("persona", "contribution"):
                continue
            # If merge and persona, upsert by (collaboration_session_id, entity_type='persona', persona_id)
            if merge and ent_type == "persona" and isinstance(it.get("persona_id"), str):
                existing = next(
                    (e for e in col_entities if isinstance(e, dict) and e.get("collaboration_session_id") == parent and e.get("entity_type") == "persona" and e.get("persona_id") == it.get("persona_id")),
                    None
                )
                if existing:
                    # update persona fields
                    for f in (
                        "persona_name", "persona_expertise", "persona_background", "persona_perspective",
                        "persona_biases", "persona_comm_style", "persona_comm_tone", "iteration"
                    ):
                        if f in it:
                            existing[f] = it.get(f)
                    existing["updated_at"] = now
                    continue
            new_e = copy.deepcopy(it)
            new_e["id"] = _gen_id("ct_ent")
            new_e["collaboration_session_id"] = parent
            new_e["created_at"] = now
            new_e["updated_at"] = now
            col_entities.append(new_e)

    # Scientific inquiries by (session_id, external_inquiry_id)
    if isinstance(in_sci, list):
        for it in in_sci:
            if not isinstance(it, dict):
                continue
            if it.get("status") == "deleted":
                continue
            sid = _sid_of(it)
            ext_iid = it.get("external_inquiry_id")
            if not isinstance(ext_iid, str) or not (1 <= len(ext_iid) <= 128):
                continue
            existing = None
            if merge:
                existing = next(
                    (q for q in sci if isinstance(q, dict) and q.get("session_id") == sid and q.get("status") != "deleted" and q.get("external_inquiry_id") == ext_iid),
                    None
                )
            if existing:
                for f in ("status", "stage", "observation", "question", "analysis", "conclusion", "iteration", "next_stage_needed", "hypothesis", "experiment"):
                    if f in it:
                        existing[f] = it.get(f)
                existing["updated_at"] = now
            else:
                new_q = copy.deepcopy(it)
                new_q["id"] = _gen_id("ct_inq")
                new_q["session_id"] = sid
                new_q["status"] = it.get("status") if it.get("status") in ("active", "completed") else "active"
                new_q["created_at"] = now
                new_q["updated_at"] = now
                sci.append(new_q)

    # Persist all
    _save("sessions.json", sessions)
    _save("thoughts.json", thoughts)
    _save("artifacts.json", artifacts)
    _save("collaboration_sessions.json", col_sessions)
    _save("collaboration_entities.json", col_entities)
    _save("scientific_inquiries.json", sci)

    # Update session caches and last_activity_at
    ta, tt, tb = _recompute_session_caches(target_session_id)
    target_session["total_artifacts"] = ta
    target_session["total_thoughts"] = tt
    target_session["total_branches"] = tb
    target_session["last_activity_at"] = now
    target_session["updated_at"] = now
    _save("sessions.json", sessions)

    # Return resulting session state (non-deleted only)
    out = {
        "session": target_session,
        "thoughts": [t for t in thoughts if isinstance(t, dict) and t.get("session_id") == target_session_id and t.get("status") != "deleted"],
        "artifacts": [a for a in artifacts if isinstance(a, dict) and a.get("session_id") == target_session_id and a.get("status") != "deleted"],
        "collaboration_sessions": [c for c in col_sessions if isinstance(c, dict) and c.get("session_id") == target_session_id and c.get("status") != "deleted"],
        "collaboration_entities": [],
        "scientific_inquiries": [q for q in sci if isinstance(q, dict) and q.get("session_id") == target_session_id and q.get("status") != "deleted"],
    }
    col_ids = set(c.get("id") for c in out["collaboration_sessions"] if isinstance(c, dict))
    out["collaboration_entities"] = [e for e in col_entities if isinstance(e, dict) and e.get("collaboration_session_id") in col_ids]

    _append_request_log("success", meta={"merge": merge, "created_new_session": created_new_session, "session_id": target_session_id})
    return out

def listsessions(apiKey, status=None, query=None, clientSessionKey=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0550000" if __import__("os").path.isdir("./environment_mix/0550000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, credential=None, extra=None):
        logs = _load("request_logs.json")
        row = {
            "id": f"ct_req_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": "listsessions",
            "credential": credential,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now
        }
        if extra:
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)

    # Basic validation
    if not isinstance(apiKey, str) or not apiKey:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "apiKey must be a non-empty string")
    if status is not None:
        if not isinstance(status, str):
            _log("VALIDATION_ERROR", apiKey)
            return _err("VALIDATION_ERROR", "status must be a string")
        if status not in ("active", "archived", "deleted"):
            _log("VALIDATION_ERROR", apiKey)
            return _err("VALIDATION_ERROR", "Invalid status filter")
    if query is not None and not isinstance(query, str):
        _log("VALIDATION_ERROR", apiKey)
        return _err("VALIDATION_ERROR", "query must be a string")
    if clientSessionKey is not None and not isinstance(clientSessionKey, str):
        _log("VALIDATION_ERROR", apiKey)
        return _err("VALIDATION_ERROR", "clientSessionKey must be a string")
    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        _log("VALIDATION_ERROR", apiKey)
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 200:
        _log("VALIDATION_ERROR", apiKey)
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200")
    if cursor is not None and not isinstance(cursor, str):
        _log("VALIDATION_ERROR", apiKey)
        return _err("VALIDATION_ERROR", "cursor must be a string")

    # Authenticate apiKey: since no keys schema provided, accept if it matches any stored credential record if present.
    # If no credential store exists, treat as ambiently valid (do not refuse well-formed requests).
    keys = _load("api_keys.json")
    if keys:
        matched = None
        for k in keys:
            if apiKey == k.get("id") or apiKey == k.get("api_key") or apiKey == k.get("key") or apiKey == k.get("value"):
                matched = k
                break
        if matched is None:
            _log("UNAUTHORIZED", apiKey)
            return _err("UNAUTHORIZED", "Invalid apiKey")

    # Enforce a simple read quota if usage store exists
    usage = _load("usage.json")
    if usage and isinstance(usage, list):
        # find bucket for apiKey
        row = None
        for r in usage:
            if r.get("credential") == apiKey:
                row = r
                break
        if row:
            quota = row.get("read_quota")
            used = row.get("read_used", 0)
            if isinstance(quota, int) and quota >= 0 and isinstance(used, int) and used >= quota:
                _log("QUOTA_EXCEEDED", apiKey)
                return _err("QUOTA_EXCEEDED", "Read quota exceeded")
            row["read_used"] = int(used) + 1
            row["updated_at"] = now
            _save("usage.json", usage)

    sessions = _load("sessions.json")

    def _ts(v):
        if not v:
            return None
        try:
            if isinstance(v, str) and v.endswith("Z"):
                v = v[:-1]
            return datetime.datetime.fromisoformat(v)
        except Exception:
            return None

    # Cursor decode: base64(json) {"lastActivityAt": "...", "id": "..."}
    cursor_obj = None
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            cursor_obj = json.loads(raw.decode("utf-8"))
        except Exception:
            _log("VALIDATION_ERROR", apiKey)
            return _err("VALIDATION_ERROR", "Invalid cursor")

    # Filter
    q = (query or "").casefold() if query else None
    out = []
    for s in sessions:
        if status is not None and s.get("status") != status:
            continue
        if clientSessionKey is not None and s.get("client_session_key") != clientSessionKey:
            continue
        if q is not None:
            title = (s.get("title") or "").casefold()
            if q not in title:
                continue
        out.append(s)

    # Sort by last_activity_at desc (nulls last), then created_at desc, then id desc for stability
    def _sort_key(s):
        la = _ts(s.get("last_activity_at"))
        ca = _ts(s.get("created_at"))
        return (
            la if la is not None else datetime.datetime(1970, 1, 1),
            ca if ca is not None else datetime.datetime(1970, 1, 1),
            s.get("id") or ""
        )
    out.sort(key=_sort_key, reverse=True)

    # Apply cursor
    if cursor_obj:
        cla = cursor_obj.get("lastActivityAt")
        cid = cursor_obj.get("id")
        cla_dt = _ts(cla)
        def _after(s):
            sla = _ts(s.get("last_activity_at")) or datetime.datetime(1970, 1, 1)
            sid = s.get("id") or ""
            # because we sort desc, "after cursor" means strictly less than cursor tuple
            ctuple = (cla_dt or datetime.datetime(1970, 1, 1), cid or "")
            stuple = (sla, sid)
            return stuple < ctuple
        out = [s for s in out if _after(s)]

    total = len(out)
    page = out[:limit]
    has_more = total > limit

    next_cursor = None
    if has_more and page:
        last = page[-1]
        obj = {"lastActivityAt": last.get("last_activity_at"), "id": last.get("id")}
        next_cursor = base64.urlsafe_b64encode(json.dumps(obj, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    # Response envelope
    resp = {
        "data": [{
            "id": s.get("id"),
            "status": s.get("status"),
            "title": s.get("title"),
            "clientSessionKey": s.get("client_session_key"),
            "createdAt": s.get("created_at"),
            "updatedAt": s.get("updated_at"),
            "lastActivityAt": s.get("last_activity_at"),
            "totals": {
                "artifacts": s.get("total_artifacts", 0),
                "thoughts": s.get("total_thoughts", 0),
                "branches": s.get("total_branches", 0)
            }
        } for s in page],
        "meta": {
            "limit": limit,
            "total": total,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

    _log("OK", apiKey, extra={"returned": len(page), "total": total})
    return resp

def getsession(apiKey, sessionId, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0550000" if __import__("os").path.isdir("./environment_mix/0550000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(endpoint, credential, status, latency_ms, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "credential": credential,
            "status": status,
            "latency_ms": latency_ms,
            "timestamp": _now_iso(),
        }
        if isinstance(meta, dict):
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits(credential, endpoint):
        cfg = _load("rate_limits.json")
        if not isinstance(cfg, dict):
            cfg = {}
        rate = cfg.get("rate_limit_per_minute", 120)
        quota = cfg.get("daily_quota", 5000)

        now = datetime.datetime.now(datetime.timezone.utc)
        minute_ago = now - datetime.timedelta(seconds=60)
        day_ago = now - datetime.timedelta(days=1)

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []

        def _parse_ts(s):
            if not isinstance(s, str):
                return None
            try:
                return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            except Exception:
                return None

        recent_min = 0
        recent_day = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("credential") != credential:
                continue
            ts = _parse_ts(r.get("timestamp"))
            if not ts:
                continue
            if ts >= minute_ago:
                recent_min += 1
            if ts >= day_ago:
                recent_day += 1

        if isinstance(rate, int) and rate >= 0 and recent_min >= rate:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        if isinstance(quota, int) and quota >= 0 and recent_day >= quota:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    t0 = time.time()

    # Validate inputs
    if not isinstance(apiKey, str) or not apiKey.strip():
        latency = int((time.time() - t0) * 1000)
        _log("getsession", str(apiKey) if apiKey is not None else None, "VALIDATION_ERROR", latency)
        return _err("VALIDATION_ERROR", "apiKey must be a non-empty string.")
    if not isinstance(sessionId, str) or not sessionId.strip():
        latency = int((time.time() - t0) * 1000)
        _log("getsession", apiKey, "VALIDATION_ERROR", latency)
        return _err("VALIDATION_ERROR", "sessionId must be a non-empty string.")

    limit_err = _enforce_limits(apiKey, "getsession")
    if limit_err:
        latency = int((time.time() - t0) * 1000)
        _log("getsession", apiKey, limit_err["error"]["code"], latency)
        return limit_err

    # Authenticate: match apiKey against a credential store if present; otherwise accept (offline store).
    creds = _load("api_keys.json")
    if isinstance(creds, list) and creds:
        ok = False
        for c in creds:
            if isinstance(c, dict) and (c.get("id") == apiKey or c.get("value") == apiKey or c.get("apiKey") == apiKey):
                if c.get("status") in (None, "active", True):
                    ok = True
                    break
        if not ok:
            latency = int((time.time() - t0) * 1000)
            _log("getsession", apiKey, "UNAUTHORIZED", latency)
            return _err("UNAUTHORIZED", "Invalid API key.")

    sessions = _load("sessions.json")
    if not isinstance(sessions, list):
        sessions = []

    sess = None
    for s in sessions:
        if isinstance(s, dict) and s.get("id") == sessionId:
            sess = s
            break

    if not sess or sess.get("status") == "deleted":
        latency = int((time.time() - t0) * 1000)
        _log("getsession", apiKey, "NOT_FOUND", latency, meta={"sessionId": sessionId})
        return _err("NOT_FOUND", "Session not found.")

    latency = int((time.time() - t0) * 1000)
    _log("getsession", apiKey, "OK", latency, meta={"sessionId": sessionId})

    return {"session": sess}

