        now = datetime.datetime.now(datetime.timezone.utc)
        minute_ago = now - datetime.timedelta(seconds=60)
        day_ago = now - datetime.timedelta(days=1)

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []

        def _parse_ts(s):
            if not isinstance(s, str):
                return None
            try:
                return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            except Exception:
                return None

        recent_min = 0
        recent_day = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("credential") != credential:
                continue
            ts = _parse_ts(r.get("timestamp"))
            if not ts:
                continue
            if ts >= minute_ago:
                recent_min += 1
            if ts >= day_ago:
                recent_day += 1

        if isinstance(rate, int) and rate >= 0 and recent_min >= rate:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        if isinstance(quota, int) and quota >= 0 and recent_day >= quota:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    def _new_id(prefix):
        return prefix + "_" + uuid.uuid4().hex

    t0 = time.time()

    # Validate inputs
    if not isinstance(apiKey, str) or not apiKey.strip():
        latency = int((time.time() - t0) * 1000)
        _log("createsession", str(apiKey) if apiKey is not None else None, "VALIDATION_ERROR", latency)
        return _err("VALIDATION_ERROR", "apiKey must be a non-empty string.")
    if not isinstance(title, str) or not title.strip():
        latency = int((time.time() - t0) * 1000)
        _log("createsession", apiKey, "VALIDATION_ERROR", latency)
        return _err("VALIDATION_ERROR", "title must be a non-empty string.")
    if clientSessionKey is not None and (not isinstance(clientSessionKey, str) or not clientSessionKey.strip()):
        latency = int((time.time() - t0) * 1000)
        _log("createsession", apiKey, "VALIDATION_ERROR", latency)
        return _err("VALIDATION_ERROR", "clientSessionKey must be a non-empty string when provided.")

    limit_err = _enforce_limits(apiKey, "createsession")
    if limit_err:
        latency = int((time.time() - t0) * 1000)
        _log("createsession", apiKey, limit_err["error"]["code"], latency)
        return limit_err

    # Authenticate if store exists
    creds = _load("api_keys.json")
    if isinstance(creds, list) and creds:
        ok = False
        for c in creds:
            if isinstance(c, dict) and (c.get("id") == apiKey or c.get("value") == apiKey or c.get("apiKey") == apiKey):
                if c.get("status") in (None, "active", True):
                    ok = True
                    break
        if not ok:
            latency = int((time.time() - t0) * 1000)
            _log("createsession", apiKey, "UNAUTHORIZED", latency)
            return _err("UNAUTHORIZED", "Invalid API key.")

    sessions = _load("sessions.json")
    if not isinstance(sessions, list):
        sessions = []

    # Enforce unique(client_session_key) where not null
    if clientSessionKey is not None:
        for s in sessions:
            if isinstance(s, dict) and s.get("client_session_key") == clientSessionKey and s.get("status") != "deleted":
                latency = int((time.time() - t0) * 1000)
                _log("createsession", apiKey, "CONFLICT", latency, meta={"clientSessionKey": clientSessionKey})
                return _err("CONFLICT", "clientSessionKey already exists.", field="clientSessionKey")

    now = _now_iso()
    new_session = {
        "id": _new_id("sess"),
        "status": "active",
        "title": title,
        "client_session_key": clientSessionKey,
        "last_activity_at": None,
        "total_artifacts": 0,
        "total_thoughts": 0,
        "total_branches": 0,
        "created_at": now,
        "updated_at": now,
    }

    sessions.append(new_session)
    _save("sessions.json", sessions)

    latency = int((time.time() - t0) * 1000)
    _log("createsession", apiKey, "OK", latency, meta={"sessionId": new_session["id"]})

    return {"session": new_session}

def updatesession(apiKey, sessionId, title=None, status=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0550000" if __import__("os").path.isdir("./environment_mix/0550000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _append_request_log(status_s, credential=None, error_code=None, error_message=None, meta=None):
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "updatesession",
            "credential": credential,
            "status": status_s,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": latency_ms,
            "timestamp": now,
        }
        if isinstance(meta, dict):
            row["meta"] = meta

        # best-effort logging to whichever store exists
        for fname in ("request_logs.json", "requests.json", "usage.json", "audit_logs.json"):
            path = os.path.join(_DB, fname)
            if not os.path.exists(path):
                continue
            data = _load(fname)
            if isinstance(data, list):
                data.append(row)
                _save(fname, data)
                return
            if isinstance(data, dict):
                if isinstance(data.get("requests"), list):
                    data["requests"].append(row)
                    _save(fname, data)
                    return
                if isinstance(data.get("rows"), list):
                    data["rows"].append(row)
                    _save(fname, data)
                    return

    def _is_nonempty_str(x):
        return isinstance(x, str) and x != ""

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _normalize_store(x):
        # collections may be stored as list of rows or {"rows":[...]}
        if isinstance(x, dict) and isinstance(x.get("rows"), list):
            return x["rows"], x
        if isinstance(x, list):
            return x, None
        return [], None

    def _save_store(filename, rows, wrapper):
        if wrapper is None:
            _save(filename, rows)
        else:
            wrapper["rows"] = rows
            _save(filename, wrapper)

    def _cascade_soft_delete(session_id):
        # Soft-delete children by setting status/entity lifecycle to deleted where applicable.
        # This must be consistent within this mutation.
        # thoughts: status -> deleted (terminal)
        th_data = _load("thoughts.json")
        th_rows, th_wrap = _normalize_store(th_data)
        changed = False
        for r in th_rows:
            if r.get("session_id") == session_id and r.get("status") != "deleted":
                r["status"] = "deleted"
                r["updated_at"] = now
                changed = True
        if changed:
            _save_store("thoughts.json", th_rows, th_wrap)

        # artifacts: status -> deleted
        ar_data = _load("artifacts.json")
        ar_rows, ar_wrap = _normalize_store(ar_data)
        changed = False
        for r in ar_rows:
            if r.get("session_id") == session_id and r.get("status") != "deleted":
                r["status"] = "deleted"
                r["updated_at"] = now
                changed = True
        if changed:
            _save_store("artifacts.json", ar_rows, ar_wrap)

        # collaboration_sessions: status -> deleted
        cs_data = _load("collaboration_sessions.json")
        cs_rows, cs_wrap = _normalize_store(cs_data)
        deleted_collab_ids = set()
        changed = False
        for r in cs_rows:
            if r.get("session_id") == session_id and r.get("status") != "deleted":
                r["status"] = "deleted"
                r["updated_at"] = now
                changed = True
            if r.get("session_id") == session_id and r.get("status") == "deleted":
                if isinstance(r.get("id"), str):
                    deleted_collab_ids.add(r["id"])
        # Also capture ids even if we just marked them deleted
        for r in cs_rows:
            if r.get("session_id") == session_id and r.get("status") == "deleted" and isinstance(r.get("id"), str):
                deleted_collab_ids.add(r["id"])
        if changed:
            _save_store("collaboration_sessions.json", cs_rows, cs_wrap)

        # collaboration_entities: hard or soft? no status field; delete by removing rows for deleted collab sessions
        # (acts as cascade delete)
        if deleted_collab_ids:
            ce_data = _load("collaboration_entities.json")
            ce_rows, ce_wrap = _normalize_store(ce_data)
            new_rows = [r for r in ce_rows if r.get("collaboration_session_id") not in deleted_collab_ids]
            if len(new_rows) != len(ce_rows):
                _save_store("collaboration_entities.json", new_rows, ce_wrap)

        # scientific_inquiries: status -> deleted
        si_data = _load("scientific_inquiries.json")
        si_rows, si_wrap = _normalize_store(si_data)
        changed = False
        for r in si_rows:
            if r.get("session_id") == session_id and r.get("status") != "deleted":
                r["status"] = "deleted"
                r["updated_at"] = now
                changed = True
        if changed:
            _save_store("scientific_inquiries.json", si_rows, si_wrap)

    # --------- validate inputs ----------
    if not _is_nonempty_str(apiKey):
        _append_request_log("error", credential=apiKey, error_code="VALIDATION_ERROR", error_message="apiKey must be a non-empty string")
        return _err("VALIDATION_ERROR", "apiKey must be a non-empty string")

    if not _is_nonempty_str(sessionId):
        _append_request_log("error", credential=apiKey, error_code="VALIDATION_ERROR", error_message="sessionId must be a non-empty string")
        return _err("VALIDATION_ERROR", "sessionId must be a non-empty string")

    if title is not None and not isinstance(title, str):
        _append_request_log("error", credential=apiKey, error_code="VALIDATION_ERROR", error_message="title must be a string")
        return _err("VALIDATION_ERROR", "title must be a string")

    allowed_status = {"active", "archived", "deleted"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _append_request_log("error", credential=apiKey, error_code="VALIDATION_ERROR", error_message="status must be one of: active, archived, deleted")
            return _err("VALIDATION_ERROR", "status must be one of: active, archived, deleted")

    if title is None and status is None:
        _append_request_log("error", credential=apiKey, error_code="VALIDATION_ERROR", error_message="At least one of title or status must be provided")
        return _err("VALIDATION_ERROR", "At least one of title or status must be provided")

    # --------- authenticate (ambient-ish) ----------
    # The tool signature includes apiKey but datastore has no credentials collection in schema.
    # Real behavior for this offline store: accept if the referenced session exists; otherwise UNAUTHORIZED only if nothing can serve the call.
    sess_data = _load("sessions.json")
    sess_rows, sess_wrap = _normalize_store(sess_data)

    target = None
    for r in sess_rows:
        if r.get("id") == sessionId:
            target = r
            break

    if target is None:
        # If the store cannot find the session, it's NOT_FOUND rather than UNAUTHORIZED.
        _append_request_log("error", credential=apiKey, error_code="NOT_FOUND", error_message="Session not found", meta={"sessionId": sessionId})
        return _err("NOT_FOUND", "Session not found", sessionId=sessionId)

    # Refuse updates to deleted sessions.
    if target.get("status") == "deleted":
        _append_request_log("error", credential=apiKey, error_code="INVALID_TRANSITION", error_message="Cannot update a deleted session", meta={"sessionId": sessionId})
        return _err("INVALID_TRANSITION", "Cannot update a deleted session", sessionId=sessionId)

    # --------- apply updates with lifecycle rules ----------
    current_status = target.get("status")
    transitions = {
        "active": {"archived", "deleted"},
        "archived": {"active", "deleted"},
        "deleted": set(),
    }

    changed_fields = {}
    # title is nullable; allow setting to empty string too (still a valid string). Only treat as change if different.
    if title is not None and title != target.get("title"):
        changed_fields["title"] = title

    status_change = None
    if status is not None and status != current_status:
        if current_status not in transitions or status not in transitions[current_status]:
            _append_request_log(
                "error",
                credential=apiKey,
                error_code="INVALID_TRANSITION",
                error_message=f"Invalid session status transition: {current_status} -> {status}",
                meta={"from": current_status, "to": status, "sessionId": sessionId},
            )
            return _err("INVALID_TRANSITION", f"Invalid session status transition: {current_status} -> {status}", from_status=current_status, to_status=status)
        status_change = status
        changed_fields["status"] = status_change

    if not changed_fields:
        # Real APIs typically return the existing resource for idempotent update calls.
        # Do NOT return CONFLICT for "no changes".
        _append_request_log("ok", credential=apiKey, meta={"sessionId": sessionId, "idempotent": True})
        return {"session": target, "idempotent": True}

    # Update timestamps; enforce last_activity_at constraint if present
    target_updated = False
    for k, v in changed_fields.items():
        target[k] = v
        target_updated = True

    # updated_at always moves on a successful mutation
    target["updated_at"] = now

    # If transitioning to deleted, cascade delete children and keep last_activity_at >= created_at constraint.
    if status_change == "deleted":
        _cascade_soft_delete(sessionId)
        # last_activity_at should at least be now; but ensure it is not before created_at
        created = _parse_dt(target.get("created_at"))
        if created is None:
            target["last_activity_at"] = now
        else:
            la = _parse_dt(target.get("last_activity_at"))
            if la is None or la < created:
                target["last_activity_at"] = target.get("created_at")
            else:
                # bump to now to reflect this activity, still >= created_at
                target["last_activity_at"] = now
        # cached counters become 0 after cascade deletion to reflect deleted children in active exports/info
        # (since deleted children should not be counted)
        target["total_artifacts"] = 0
        target["total_thoughts"] = 0
        target["total_branches"] = 0

    # persist session
    _save_store("sessions.json", sess_rows, sess_wrap)

    _append_request_log("ok", credential=apiKey, meta={"sessionId": sessionId, "changed": sorted(list(changed_fields.keys()))})
    return {"session": target, "changed": changed_fields}

def sessionexport(apiKey, sessionId, format=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0550000" if __import__("os").path.isdir("./environment_mix/0550000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(endpoint, credential, status, latency_ms, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "credential": credential,
            "status": status,
            "latency_ms": latency_ms,
            "timestamp": _now_iso(),
        }
        if isinstance(meta, dict):
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits(credential, endpoint):
        cfg = _load("rate_limits.json")
        if not isinstance(cfg, dict):
            cfg = {}
        rate = cfg.get("rate_limit_per_minute", 120)
        quota = cfg.get("daily_quota", 5000)

        now = datetime.datetime.now(datetime.timezone.utc)
        minute_ago = now - datetime.timedelta(seconds=60)
        day_ago = now - datetime.timedelta(days=1)

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []

        def _parse_ts(s):
            if not isinstance(s, str):
                return None
            try:
                return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            except Exception:
                return None

        recent_min = 0
        recent_day = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("credential") != credential:
                continue
            ts = _parse_ts(r.get("timestamp"))
            if not ts:
                continue
            if ts >= minute_ago:
                recent_min += 1
            if ts >= day_ago:
                recent_day += 1

        if isinstance(rate, int) and rate >= 0 and recent_min >= rate:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        if isinstance(quota, int) and quota >= 0 and recent_day >= quota:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    def _preview(s, n=200):
        if s is None:
            return None
        if not isinstance(s, str):
            s = str(s)
        s = s.strip()
        if len(s) <= n:
            return s
        return s[:n]

    t0 = time.time()

    # Validate inputs
    if not isinstance(apiKey, str) or not apiKey.strip():
        latency = int((time.time() - t0) * 1000)
        _log("sessionexport", str(apiKey) if apiKey is not None else None, "VALIDATION_ERROR", latency)
        return _err("VALIDATION_ERROR", "apiKey must be a non-empty string.")
    if not isinstance(sessionId, str) or not sessionId.strip():
        latency = int((time.time() - t0) * 1000)
        _log("sessionexport", apiKey, "VALIDATION_ERROR", latency)
        return _err("VALIDATION_ERROR", "sessionId must be a non-empty string.")
    if format is None:
        format = "json"
    if not isinstance(format, str) or format not in ("json", "summary"):
        latency = int((time.time() - t0) * 1000)
        _log("sessionexport", apiKey, "VALIDATION_ERROR", latency)
        return _err("VALIDATION_ERROR", "format must be one of: json, summary.", allowed=["json", "summary"])

    limit_err = _enforce_limits(apiKey, "sessionexport")
    if limit_err:
        latency = int((time.time() - t0) * 1000)
        _log("sessionexport", apiKey, limit_err["error"]["code"], latency)
        return limit_err

    # Authenticate if store exists
    creds = _load("api_keys.json")
    if isinstance(creds, list) and creds:
        ok = False
        for c in creds:
            if isinstance(c, dict) and (c.get("id") == apiKey or c.get("value") == apiKey or c.get("apiKey") == apiKey):
                if c.get("status") in (None, "active", True):
                    ok = True
                    break
        if not ok:
            latency = int((time.time() - t0) * 1000)
            _log("sessionexport", apiKey, "UNAUTHORIZED", latency)
            return _err("UNAUTHORIZED", "Invalid API key.")

    # Consistent snapshot: load everything first, then filter in-memory (single read phase).
    sessions = _load("sessions.json")
    thoughts = _load("thoughts.json")
    artifacts = _load("artifacts.json")
    collab_sessions = _load("collaboration_sessions.json")
    collab_entities = _load("collaboration_entities.json")
    inquiries = _load("scientific_inquiries.json")

    if not isinstance(sessions, list):
        sessions = []
    if not isinstance(thoughts, list):
        thoughts = []
    if not isinstance(artifacts, list):
        artifacts = []
    if not isinstance(collab_sessions, list):
        collab_sessions = []
    if not isinstance(collab_entities, list):
        collab_entities = []
    if not isinstance(inquiries, list):
        inquiries = []

    sess = None
    for s in sessions:
        if isinstance(s, dict) and s.get("id") == sessionId:
            sess = s
            break

    if not sess or sess.get("status") == "deleted":
        latency = int((time.time() - t0) * 1000)
        _log("sessionexport", apiKey, "NOT_FOUND", latency, meta={"sessionId": sessionId})
        return _err("NOT_FOUND", "Session not found.")

    # Filter non-deleted related entities (business rule)
    th = [t for t in thoughts if isinstance(t, dict) and t.get("session_id") == sessionId and t.get("status") != "deleted"]
    ar = [a for a in artifacts if isinstance(a, dict) and a.get("session_id") == sessionId and a.get("status") != "deleted"]
    cs = [c for c in collab_sessions if isinstance(c, dict) and c.get("session_id") == sessionId and c.get("status") != "deleted"]
    cs_ids = set([c.get("id") for c in cs if isinstance(c.get("id"), str)])
    ce = [e for e in collab_entities if isinstance(e, dict) and e.get("collaboration_session_id") in cs_ids]
    si = [q for q in inquiries if isinstance(q, dict) and q.get("session_id") == sessionId and q.get("status") != "deleted"]

    # Sort by created_at desc where present for previews
    def _ts(o):
        v = o.get("created_at") if isinstance(o, dict) else None
        if not isinstance(v, str):
            return ""
        return v
    th_sorted = sorted(th, key=_ts, reverse=True)
    ar_sorted = sorted(ar, key=_ts, reverse=True)
    cs_sorted = sorted(cs, key=_ts, reverse=True)
    si_sorted = sorted(si, key=_ts, reverse=True)

    if format == "json":
        out = {
            "format": "json",
            "snapshot_at": _now_iso(),
            "session": sess,
            "thoughts": th_sorted,
            "artifacts": ar_sorted,
            "collaborationSessions": cs_sorted,
            "collaborationEntities": ce,
            "scientificInquiries": si_sorted,
        }
    else:
        # Summary: omit payload blobs; include counts + recent previews.
        recent_thoughts = [{
            "id": t.get("id"),
            "status": t.get("status"),
            "thought_number": t.get("thought_number"),
            "branch_id": t.get("branch_id"),
            "is_revision": t.get("is_revision"),
            "created_at": t.get("created_at"),
            "preview": _preview(t.get("thought")),
        } for t in th_sorted[:10]]

        recent_artifacts = [{
            "id": a.get("id"),
            "status": a.get("status"),
            "tool_name": a.get("tool_name"),
            "external_object_id": a.get("external_object_id"),
            "iteration": a.get("iteration"),
            "stage": a.get("stage"),
            "next_needed": a.get("next_needed"),
            "created_at": a.get("created_at"),
            "payload_keys": list(a.get("payload", {}).keys()) if isinstance(a.get("payload"), dict) else None,
        } for a in ar_sorted[:10]]

        recent_collab = [{
            "id": c.get("id"),
            "status": c.get("status"),
            "external_session_id": c.get("external_session_id"),
            "topic": _preview(c.get("topic")),
            "stage": c.get("stage"),
            "iteration": c.get("iteration"),
            "created_at": c.get("created_at"),
        } for c in cs_sorted[:5]]

        # Contributions previews (from entities)
        contrib = [e for e in ce if isinstance(e, dict) and e.get("entity_type") == "contribution"]
        contrib_sorted = sorted(contrib, key=_ts, reverse=True)
        recent_contrib = [{
            "id": e.get("id"),
            "persona_id": e.get("persona_id"),
            "contribution_type": e.get("contribution_type"),
            "confidence": e.get("contribution_confidence"),
            "created_at": e.get("created_at"),
            "preview": _preview(e.get("contribution_content")),
        } for e in contrib_sorted[:10]]

        recent_inquiries = [{
            "id": q.get("id"),
            "status": q.get("status"),
            "external_inquiry_id": q.get("external_inquiry_id"),
            "stage": q.get("stage"),
            "iteration": q.get("iteration"),
            "created_at": q.get("created_at"),
            "observation_preview": _preview(q.get("observation")),
            "question_preview": _preview(q.get("question")),
            "analysis_preview": _preview(q.get("analysis")),
            "conclusion_preview": _preview(q.get("conclusion")),
        } for q in si_sorted[:5]]

        out = {
            "format": "summary",
            "snapshot_at": _now_iso(),
            "session": {
                "id": sess.get("id"),
                "status": sess.get("status"),
                "title": sess.get("title"),
                "client_session_key": sess.get("client_session_key"),
                "last_activity_at": sess.get("last_activity_at"),
                "total_artifacts": sess.get("total_artifacts"),
                "total_thoughts": sess.get("total_thoughts"),
                "total_branches": sess.get("total_branches"),
                "created_at": sess.get("created_at"),
                "updated_at": sess.get("updated_at"),
            },
            "counts": {
                "thoughts": len(th),
                "artifacts": len(ar),
                "collaborationSessions": len(cs),
                "collaborationEntities": len(ce),
                "scientificInquiries": len(si),
            },
            "recent": {
                "thoughts": recent_thoughts,
                "artifacts": recent_artifacts,
                "collaborationSessions": recent_collab,
                "collaborationContributions": recent_contrib,
                "scientificInquiries": recent_inquiries,
            },
        }

    latency = int((time.time() - t0) * 1000)
    _log("sessionexport", apiKey, "OK", latency, meta={"sessionId": sessionId, "format": format})
    return {"export": out}

def sessionimport(apiKey, sessionData, merge=None, **_extra):
    import json, os, datetime, time, uuid, copy

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0550000" if __import__("os").path.isdir("./environment_mix/0550000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _append_request_log(status, credential=None, error_code=None, error_message=None, meta=None):
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "sessionimport",
            "credential": credential,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": latency_ms,
            "timestamp": now,
        }
        if isinstance(meta, dict):
            row["meta"] = meta
        for fname in ("request_logs.json", "requests.json", "usage.json", "audit_logs.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                data = _load(fname)
                if isinstance(data, list):
                    data.append(row)
                    _save(fname, data)
                elif isinstance(data, dict) and isinstance(data.get("requests"), list):
                    data["requests"].append(row)
                    _save(fname, data)
                break

    def _all_credential_rows():
        rows_out = []
        for fname in ("credentials.json", "api_keys.json", "apikeys.json", "keys.json"):
            path = os.path.join(_DB, fname)
            if not os.path.exists(path):
                continue
            rows = _load(fname)
            if isinstance(rows, list):
                for r in rows:
                    if isinstance(r, dict):
                        rows_out.append(r)
            elif isinstance(rows, dict) and isinstance(rows.get("rows"), list):
                for r in rows.get("rows", []):
                    if isinstance(r, dict):
                        rows_out.append(r)
        return rows_out

    def _resolve_credential(key_value):
        # Match by visible value or id; never by hash/ciphertext.
        if not isinstance(key_value, str) or not key_value.strip():
            return None
        key_value = key_value.strip()

        candidates = []
        for r in _all_credential_rows():
            st = r.get("status")
            if st in ("revoked", "disabled", "deleted", "inactive"):
                continue
            visible_fields = (
                r.get("key"),
                r.get("apiKey"),
                r.get("apikey"),
                r.get("token"),
                r.get("value"),
                r.get("secret"),
                r.get("client_key"),
            )
            if r.get("id") == key_value or any(v == key_value for v in visible_fields if isinstance(v, str)):
                candidates.append(r)
        if candidates:
            return candidates[0]

        # Fallback: some stores have no credentials; accept existing session ids as ambient apiKey.
        sess_rows = _load("sessions.json")
        if isinstance(sess_rows, list) and any(isinstance(s, dict) and s.get("id") == key_value for s in sess_rows):
            return {"id": key_value, "key": key_value, "status": "active", "_fallback": "session_id_as_key"}
        return None

    def _new_id(prefix):
        # ULID-like enough for local store uniqueness
        return prefix + datetime.datetime.utcnow().strftime("%y%m%d%H%M%S") + "_" + uuid.uuid4().hex[:16]

    def _as_list(x):
        return x if isinstance(x, list) else ([] if x is None else None)

    # ---- Validate inputs
    if not isinstance(apiKey, str) or not apiKey.strip():
        _append_request_log("error", credential=None, error_code="VALIDATION_ERROR", error_message="apiKey must be a non-empty string")
        return _err("VALIDATION_ERROR", "apiKey must be a non-empty string")

    cred = _resolve_credential(apiKey)
    if not cred:
        _append_request_log("error", credential=None, error_code="UNAUTHORIZED", error_message="Invalid apiKey")
        return _err("UNAUTHORIZED", "Invalid apiKey")

    if merge is None:
        merge = False
    if not isinstance(merge, bool):
        _append_request_log("error", credential=cred.get("id"), error_code="VALIDATION_ERROR", error_message="merge must be boolean")
        return _err("VALIDATION_ERROR", "merge must be boolean")

    # sessionData must be a dict (already-parsed JSON). If string, parse.
    if isinstance(sessionData, str):
        try:
            sessionData = json.loads(sessionData)
        except json.JSONDecodeError:
            _append_request_log("error", credential=cred.get("id"), error_code="VALIDATION_ERROR", error_message="sessionData must be valid JSON")
            return _err("VALIDATION_ERROR", "sessionData must be valid JSON")
    if not isinstance(sessionData, dict):
        _append_request_log("error", credential=cred.get("id"), error_code="VALIDATION_ERROR", error_message="sessionData must be an object")
        return _err("VALIDATION_ERROR", "sessionData must be an object")

    if "session" not in sessionData or not isinstance(sessionData.get("session"), dict):
        _append_request_log("error", credential=cred.get("id"), error_code="VALIDATION_ERROR", error_message="sessionData.session is required")
        return _err("VALIDATION_ERROR", "sessionData.session is required and must be an object")

    sess_in = sessionData["session"]
    if not isinstance(sess_in.get("title"), str) or not sess_in.get("title").strip():
        _append_request_log("error", credential=cred.get("id"), error_code="VALIDATION_ERROR", error_message="session.title is required")
        return _err("VALIDATION_ERROR", "session.title is required")

    status_in = sess_in.get("status", "active")
    if status_in is None:
        status_in = "active"
    if not isinstance(status_in, str) or status_in not in ("active", "archived", "deleted"):
        _append_request_log("error", credential=cred.get("id"), error_code="VALIDATION_ERROR", error_message="session.status invalid")
        return _err("VALIDATION_ERROR", "session.status must be one of: active, archived, deleted")

    client_key_in = sess_in.get("client_session_key")
    if client_key_in is not None and (not isinstance(client_key_in, str) or not client_key_in.strip()):
        _append_request_log("error", credential=cred.get("id"), error_code="VALIDATION_ERROR", error_message="client_session_key must be a non-empty string when provided")
        return _err("VALIDATION_ERROR", "session.client_session_key must be a non-empty string when provided")

    for arr_name in ("thoughts", "artifacts", "collaboration_sessions", "collaboration_entities", "scientific_inquiries"):
        arr = _as_list(sessionData.get(arr_name))
        if arr is None:
            _append_request_log("error", credential=cred.get("id"), error_code="VALIDATION_ERROR", error_message=f"{arr_name} must be an array when provided")
            return _err("VALIDATION_ERROR", f"{arr_name} must be an array when provided")

    # ---- Load all collections for a consistent snapshot / single transaction-like write
    sessions = _load("sessions.json")
    thoughts = _load("thoughts.json")
    artifacts = _load("artifacts.json")
    col_sessions = _load("collaboration_sessions.json")
    col_entities = _load("collaboration_entities.json")
    sci_inq = _load("scientific_inquiries.json")

    if not isinstance(sessions, list):
        _append_request_log("error", credential=cred.get("id"), error_code="NOT_FOUND", error_message="sessions store not available")
        return _err("NOT_FOUND", "sessions store not available")

    # ---- Find / create target session
    target_session = None
    target_session_idx = None

    def _find_session_by_id(sid):
        for i, s in enumerate(sessions):
            if isinstance(s, dict) and s.get("id") == sid:
                return i, s
        return None, None

    def _find_session_by_client_key(ck):
        if ck is None:
            return None, None
        for i, s in enumerate(sessions):
            if isinstance(s, dict) and s.get("client_session_key") == ck and s.get("status") != "deleted":
                return i, s
        return None, None

    if merge:
        # Preferred: client_session_key, else session.id mapping in import header (sess_in.id)
        if client_key_in:
            target_session_idx, target_session = _find_session_by_client_key(client_key_in)
        if target_session is None and isinstance(sess_in.get("id"), str) and sess_in.get("id"):
            target_session_idx, target_session = _find_session_by_id(sess_in.get("id"))

        if target_session is None:
            # Create new if not found (upsert semantics)
            new_id = "ct_sess_" + uuid.uuid4().hex[:26]
            # enforce unique(client_session_key) where not null
            if client_key_in:
                for s in sessions:
                    if isinstance(s, dict) and s.get("client_session_key") == client_key_in and s.get("status") != "deleted":
                        _append_request_log("error", credential=cred.get("id"), error_code="CONFLICT", error_message="client_session_key already exists")
                        return _err("CONFLICT", "Constraint violated: unique(client_session_key) where client_session_key is not null")
            target_session = {
                "id": new_id,
                "status": status_in if status_in != "deleted" else "active",
                "title": sess_in.get("title"),
                "client_session_key": client_key_in,
                "last_activity_at": None,
                "total_artifacts": 0,
                "total_thoughts": 0,
                "total_branches": 0,
                "created_at": now,
                "updated_at": now,
            }
            sessions.append(target_session)
            target_session_idx = len(sessions) - 1
        else:
            if target_session.get("status") == "deleted":
                _append_request_log("error", credential=cred.get("id"), error_code="INVALID_TRANSITION", error_message="Cannot merge into a deleted session")
                return _err("INVALID_TRANSITION", "Cannot merge into a deleted session")
            # Update mutable fields (title/status) with allowed transitions
            # Use session lifecycle transitions
            cur = target_session.get("status")
            allowed = {
                "active": ("archived", "deleted"),
                "archived": ("active", "deleted"),
                "deleted": (),
            }
            desired = status_in
            if desired != cur:
                if desired not in allowed.get(cur, ()):
                    _append_request_log("error", credential=cred.get("id"), error_code="INVALID_TRANSITION", error_message=f"Invalid status transition from {cur} to {desired}")
                    return _err("INVALID_TRANSITION", f"Invalid status transition from {cur} to {desired}")
                target_session["status"] = desired
            if isinstance(sess_in.get("title"), str) and sess_in.get("title") != target_session.get("title"):
                target_session["title"] = sess_in.get("title")
            if client_key_in and client_key_in != target_session.get("client_session_key"):
                # enforce uniqueness
                for s in sessions:
                    if isinstance(s, dict) and s.get("id") != target_session.get("id") and s.get("client_session_key") == client_key_in and s.get("status") != "deleted":
                        _append_request_log("error", credential=cred.get("id"), error_code="CONFLICT", error_message="client_session_key already exists")
                        return _err("CONFLICT", "Constraint violated: unique(client_session_key) where client_session_key is not null")
                target_session["client_session_key"] = client_key_in
            target_session["updated_at"] = now
    else:
        # Create a new session always.
        if client_key_in:
            for s in sessions:
                if isinstance(s, dict) and s.get("client_session_key") == client_key_in and s.get("status") != "deleted":
                    _append_request_log("error", credential=cred.get("id"), error_code="CONFLICT", error_message="client_session_key already exists")
                    return _err("CONFLICT", "Constraint violated: unique(client_session_key) where client_session_key is not null")

        new_id = "ct_sess_" + uuid.uuid4().hex[:26]
        target_session = {
            "id": new_id,
            "status": status_in if status_in != "deleted" else "active",
            "title": sess_in.get("title"),
            "client_session_key": client_key_in,
            "last_activity_at": None,
            "total_artifacts": 0,
            "total_thoughts": 0,
            "total_branches": 0,
            "created_at": now,
            "updated_at": now,
        }
        sessions.append(target_session)
        target_session_idx = len(sessions) - 1

    target_session_id = target_session["id"]

    # ---- Helpers for upsert keys
    def _norm_branch_id(v):
        return None if v is None else v

    def _thought_natural_key(row):
        if not isinstance(row, dict):
            return None
        bn = _norm_branch_id(row.get("branch_id", row.get("branchId")))
        tn = row.get("thought_number", row.get("thoughtNumber"))
        return (bn, tn)

    def _artifact_natural_key(row):
        if not isinstance(row, dict):
            return None
        tool = row.get("tool_name", row.get("toolName"))
        ext = row.get("external_object_id", row.get("externalObjectId"))
        return (tool, ext)

    def _colsession_natural_key(row):
        if not isinstance(row, dict):
            return None
        return row.get("external_session_id", row.get("externalSessionId"))

    def _sciinq_natural_key(row):
        if not isinstance(row, dict):
            return None
        return row.get("external_inquiry_id", row.get("externalInquiryId"))

    # ---- Import thoughts
    imported_thoughts = 0
    if isinstance(thoughts, list):
        incoming = sessionData.get("thoughts") or []
        if merge:
            # index existing by (session_id, branch_id, thought_number) where status != deleted
            index = {}
            for t in thoughts:
                if isinstance(t, dict) and t.get("session_id") == target_session_id and t.get("status") != "deleted":
                    index[(t.get("branch_id"), t.get("thought_number"))] = t
            for it in incoming:
                if not isinstance(it, dict):
                    continue
                bn, tn = _thought_natural_key(it)
                if tn is None:
                    continue
                try:
                    tn_num = float(tn)
                except Exception:
                    continue
                if tn_num < 1:
                    _append_request_log("error", credential=cred.get("id"), error_code="VALIDATION_ERROR", error_message="Constraint violated: thought_number >= 1")
                    return _err("VALIDATION_ERROR", "Constraint violated: thought_number >= 1")
                tot = it.get("total_thoughts", it.get("totalThoughts"))
                if tot is None:
                    tot = tn_num
                try:
                    tot_num = float(tot)
                except Exception:
                    _append_request_log("error", credential=cred.get("id"), error_code="VALIDATION_ERROR", error_message="total_thoughts must be numeric")
                    return _err("VALIDATION_ERROR", "Constraint violated: total_thoughts >= thought_number")
                if tot_num < tn_num:
                    _append_request_log("error", credential=cred.get("id"), error_code="VALIDATION_ERROR", error_message="Constraint violated: total_thoughts >= thought_number")
                    return _err("VALIDATION_ERROR", "Constraint violated: total_thoughts >= thought_number")
                key = (bn, tn_num)
                existing = index.get(key)
                if existing is None:
                    new_row = {
                        "id": "ct_tht_" + uuid.uuid4().hex[:26],
                        "session_id": target_session_id,
                        "status": it.get("status") if it.get("status") in ("active", "superseded", "deleted") else "active",
                        "thought": it.get("thought", ""),
                        "thought_number": tn_num,
                        "total_thoughts": tot_num,
                        "next_thought_needed": bool(it.get("next_thought_needed", it.get("nextThoughtNeeded", False))),
                        "needs_more_thoughts": it.get("needs_more_thoughts", it.get("needsMoreThoughts")),
                        "branch_id": bn,
                        "branch_from_thought_number": it.get("branch_from_thought_number", it.get("branchFromThought")),
                        "is_revision": it.get("is_revision", it.get("isRevision")),
                        "revises_thought_number": it.get("revises_thought_number", it.get("revisesThought")),
                        "supersedes_thought_id": it.get("supersedes_thought_id", it.get("supersedesThoughtId")),
                        "created_at": now,
                        "updated_at": now,
                    }
                    thoughts.append(new_row)
                    index[key] = new_row
                    imported_thoughts += 1
                else:
                    # upsert mutable fields (content, flags), do not resurrect deleted
                    if existing.get("status") == "deleted":
                        continue
                    for f_in, f_out in (
                        ("thought", "thought"),
                        ("next_thought_needed", "next_thought_needed"),
                        ("needs_more_thoughts", "needs_more_thoughts"),
                    ):
                        if f_in in it:
                            existing[f_out] = it.get(f_in)
                    if "nextThoughtNeeded" in it:
                        existing["next_thought_needed"] = bool(it.get("nextThoughtNeeded"))
                    if "needsMoreThoughts" in it:
                        existing["needs_more_thoughts"] = it.get("needsMoreThoughts")
                    existing["updated_at"] = now
        else:
            for it in incoming:
                if not isinstance(it, dict):
                    continue
                # Minimal required fields for a thought row in our schema: thought, thought_number, total_thoughts, next_thought_needed
                tn = it.get("thought_number", it.get("thoughtNumber"))
                tot = it.get("total_thoughts", it.get("totalThoughts"))
                if tn is None:
                    continue
                try:
                    tn_num = float(tn)
                except Exception:
                    continue
                if tn_num < 1:
                    _append_request_log("error", credential=cred.get("id"), error_code="VALIDATION_ERROR", error_message="Constraint violated: thought_number >= 1")
                    return _err("VALIDATION_ERROR", "Constraint violated: thought_number >= 1")
                if tot is None:
                    tot = tn_num
                try:
                    tot_num = float(tot)
                except Exception:
                    _append_request_log("error", credential=cred.get("id"), error_code="VALIDATION_ERROR", error_message="total_thoughts must be numeric")
                    return _err("VALIDATION_ERROR", "Constraint violated: total_thoughts >= thought_number")
                if tot_num < tn_num:
                    _append_request_log("error", credential=cred.get("id"), error_code="VALIDATION_ERROR", error_message="Constraint violated: total_thoughts >= thought_number")
                    return _err("VALIDATION_ERROR", "Constraint violated: total_thoughts >= thought_number")
                bn = _norm_branch_id(it.get("branch_id", it.get("branchId")))
                if bn is not None and (not isinstance(bn, str) or not (1 <= len(bn) <= 128)):
                    _append_request_log("error", credential=cred.get("id"), error_code="VALIDATION_ERROR", error_message="Constraint violated: branch_id length 1..128")
                    return _err("VALIDATION_ERROR", "Constraint violated: branch_id length 1..128")
                new_row = {
                    "id": "ct_tht_" + uuid.uuid4().hex[:26],
                    "session_id": target_session_id,
                    "status": it.get("status") if it.get("status") in ("active", "superseded", "deleted") else "active",
                    "thought": it.get("thought", ""),
                    "thought_number": tn_num,
                    "total_thoughts": tot_num,
                    "next_thought_needed": bool(it.get("next_thought_needed", it.get("nextThoughtNeeded", False))),
                    "needs_more_thoughts": it.get("needs_more_thoughts", it.get("needsMoreThoughts")),
                    "branch_id": bn,
                    "branch_from_thought_number": it.get("branch_from_thought_number", it.get("branchFromThought")),
                    "is_revision": it.get("is_revision", it.get("isRevision")),
                    "revises_thought_number": it.get("revises_thought_number", it.get("revisesThought")),
                    "supersedes_thought_id": it.get("supersedes_thought_id", it.get("supersedesThoughtId")),
                    "created_at": now,
                    "updated_at": now,
                }
                thoughts.append(new_row)
                imported_thoughts += 1

    # ---- Import artifacts
    imported_artifacts = 0
    valid_tools = {
        "mentalmodel", "debuggingapproach", "socraticmethod", "creativethinking", "systemsthinking",
        "structuredargumentation", "decisionframework", "metacognitivemonitoring", "visualreasoning"
    }
    if isinstance(artifacts, list):
        incoming = sessionData.get("artifacts") or []
        if merge:
            index = {}
            for a in artifacts:
                if isinstance(a, dict) and a.get("session_id") == target_session_id and a.get("status") != "deleted":
                    index[(a.get("tool_name"), a.get("external_object_id"))] = a
            for ia in incoming:
                if not isinstance(ia, dict):
                    continue
                tool = ia.get("tool_name", ia.get("toolName"))
                if not isinstance(tool, str) or tool not in valid_tools:
                    continue
                ext = ia.get("external_object_id", ia.get("externalObjectId"))
                # enforce external id rules for specific tools if payload present
                payload = ia.get("payload")
                if payload is None and isinstance(ia.get("request"), dict):
                    payload = ia.get("request")
                if payload is None:
                    payload = ia.get("payload", {})
                if not isinstance(payload, dict):
                    _append_request_log("error", credential=cred.get("id"), error_code="VALIDATION_ERROR", error_message="Artifact payload must be an object")
                    return _err("VALIDATION_ERROR", "Constraint violated: payload must be valid JSON object")
                if tool in ("visualreasoning", "decisionframework", "metacognitivemonitoring"):
                    if not isinstance(ext, str) or not (1 <= len(ext) <= 128):
                        _append_request_log("error", credential=cred.get("id"), error_code="VALIDATION_ERROR", error_message="external_object_id required for tool")
                        return _err("VALIDATION_ERROR", f"Constraint violated: tool_name='{tool}' implies external_object_id is not null")
                    field = {"visualreasoning": "diagramId", "decisionframework": "decisionId", "metacognitivemonitoring": "monitoringId"}[tool]
                    if payload.get(field) != ext:
                        _append_request_log("error", credential=cred.get("id"), error_code="VALIDATION_ERROR", error_message="external_object_id must match payload id")
                        return _err("VALIDATION_ERROR", f"Constraint violated: payload.{field} must equal external_object_id")
                key = (tool, ext)
                existing = index.get(key)
                if existing is None:
                    new_row = {
                        "id": "ct_art_" + uuid.uuid4().hex[:26],
                        "session_id": target_session_id,
                        "status": ia.get("status") if ia.get("status") in ("active", "finalized", "deleted") else "active",
                        "tool_name": tool,
                        "external_object_id": ext,
                        "iteration": ia.get("iteration"),
                        "stage": ia.get("stage"),
                        "next_needed": ia.get("next_needed", ia.get("nextNeeded")),
                        "payload": payload,
                        "created_at": now,
                        "updated_at": now,
                    }
                    artifacts.append(new_row)
                    index[key] = new_row
                    imported_artifacts += 1
                else:
                    if existing.get("status") == "deleted":
                        continue
                    # upsert a subset
                    if "status" in ia and ia.get("status") in ("active", "finalized", "deleted"):
                        existing["status"] = ia.get("status")
                    if "iteration" in ia:
                        existing["iteration"] = ia.get("iteration")
                    if "stage" in ia:
                        existing["stage"] = ia.get("stage")
                    if "next_needed" in ia:
                        existing["next_needed"] = ia.get("next_needed")
                    if "nextNeeded" in ia:
                        existing["next_needed"] = ia.get("nextNeeded")
                    if "payload" in ia and isinstance(ia.get("payload"), dict):
                        existing["payload"] = ia.get("payload")
                    existing["updated_at"] = now
        else:
            for ia in incoming:
                if not isinstance(ia, dict):
                    continue
                tool = ia.get("tool_name", ia.get("toolName"))
                if not isinstance(tool, str) or tool not in valid_tools:
                    continue
