    # ---- Import scientific inquiries
    imported_inq = 0
    allowed_stages = {"observation", "question", "hypothesis", "experiment", "analysis", "conclusion", "iteration"}
    allowed_h_status = ["proposed", "testing", "supported", "refuted", "refined"]
    monotonic_rank = {s: i for i, s in enumerate(allowed_h_status)}

    def _validate_hypothesis(h):
        if h is None:
            return None
        if not isinstance(h, dict):
            return "hypothesis must be an object"
        if h.get("hypothesisId") is None:
            return "Constraint violated: hypothesis.hypothesisId is not null"
        st = h.get("status")
        if st is not None and st not in allowed_h_status:
            return "Constraint violated: hypothesis.status in ('proposed','testing','supported','refuted','refined')"
        conf = h.get("confidence")
        if conf is not None:
            try:
                cf = float(conf)
            except Exception:
                return "Constraint violated: hypothesis.confidence within [0,1]"
            if cf < 0 or cf > 1:
                return "Constraint violated: hypothesis.confidence within [0,1]"
        return None

    def _validate_experiment(e):
        if e is None:
            return None
        if not isinstance(e, dict):
            return "experiment must be an object"
        if e.get("experimentId") is None:
            return "Constraint violated: experiment.experimentId is not null"
        if e.get("hypothesisId") is None:
            return "Constraint violated: experiment.hypothesisId is not null"
        if e.get("controlMeasures") is None:
            return "Constraint violated: experiment.controlMeasures is not null"
        return None

    if isinstance(sci_inq, list):
        incoming = sessionData.get("scientific_inquiries") or []
        if merge:
            index = {}
            for si in sci_inq:
                if isinstance(si, dict) and si.get("session_id") == target_session_id and si.get("status") != "deleted":
                    index[si.get("external_inquiry_id")] = si
            for isi in incoming:
                if not isinstance(isi, dict):
                    continue
                ext = isi.get("external_inquiry_id", isi.get("externalInquiryId"))
                if not isinstance(ext, str) or not (1 <= len(ext) <= 128):
                    continue
                stage = isi.get("stage")
                if stage is None:
                    stage = "observation"
                if stage not in allowed_stages:
                    _append_request_log("error", credential=cred.get("id"), error_code="VALIDATION_ERROR", error_message="Invalid scientific inquiry stage")
                    return _err("VALIDATION_ERROR", "Constraint violated: scientific_inquiries.stage in allowed enum")
                hyp = isi.get("hypothesis")
                exp = isi.get("experiment")
                msg = _validate_hypothesis(hyp)
                if msg:
                    _append_request_log("error", credential=cred.get("id"), error_code="VALIDATION_ERROR", error_message=msg)
                    return _err("VALIDATION_ERROR", msg)
                msg = _validate_experiment(exp)
                if msg:
                    _append_request_log("error", credential=cred.get("id"), error_code="VALIDATION_ERROR", error_message=msg)
                    return _err("VALIDATION_ERROR", msg)
                existing = index.get(ext)
