                        "observation": isi.get("observation"),
                        "question": isi.get("question"),
                        "analysis": isi.get("analysis"),
                        "conclusion": isi.get("conclusion"),
                        "iteration": isi.get("iteration", 0),
                        "next_stage_needed": bool(isi.get("next_stage_needed", isi.get("nextStageNeeded", False))),
