                        "experiment": exp,
                        "created_at": now,
                        "updated_at": now,
                    }
                    sci_inq.append(new_row)
                    index[ext] = new_row
                    imported_inq += 1
                else:
                    if existing.get("status") == "deleted":
                        continue
                    # enforce monotonic hypothesis.status transitions except refined may follow any
                    if hyp is not None and isinstance(hyp, dict):
                        old = existing.get("hypothesis") if isinstance(existing.get("hypothesis"), dict) else None
                        old_st = old.get("status") if isinstance(old, dict) else None
                        new_st = hyp.get("status")
                        if old_st and new_st and new_st != "refined" and old_st in monotonic_rank and new_st in monotonic_rank:
                            if monotonic_rank[new_st] < monotonic_rank[old_st]:
                                _append_request_log("error", credential=cred.get("id"), error_code="INVALID_TRANSITION", error_message="hypothesis.status transition not monotonic")
                                return _err("INVALID_TRANSITION", f"Invalid hypothesis.status transition from {old_st} to {new_st}")
                    # upsert fields
                    for f in ("status", "stage", "observation", "question", "analysis", "conclusion", "iteration", "next_stage_needed"):
                        if f in isi:
                            existing[f] = isi.get(f)
                    if "nextStageNeeded" in isi:
                        existing["next_stage_needed"] = bool(isi.get("nextStageNeeded"))
                    if "hypothesis" in isi:
                        existing["hypothesis"] = hyp
                    if "experiment" in isi:
