    # ---- Update session cached counters and last_activity_at
    # Only count non-deleted rows.
    def _count_thoughts():
        if not isinstance(thoughts, list):
            return 0, 0
        cnt = 0
        branches = set()
        for t in thoughts:
            if isinstance(t, dict) and t.get("session_id") == target_session_id and t.get("status") != "deleted":
                cnt += 1
                branches.add(t.get("branch_id"))
        # branches includes None for mainline; total_branches expects distinct branchIds used, treat None as mainline branch
        # Count distinct non-null branch ids, but include mainline only if any thoughts exist
        non_null = {b for b in branches if b is not None}
        total_br = len(non_null) + (1 if cnt > 0 else 0)
        return cnt, total_br

    def _count_artifacts():
        if not isinstance(artifacts, list):
            return 0
        return sum(1 for a in artifacts if isinstance(a, dict) and a.get("session_id") == target_session_id and a.get("status") != "deleted")

    total_th, total_br = _count_thoughts()
    total_art = _count_artifacts()
    target_session["total_thoughts"] = int(total_th)
    target_session["total_branches"] = int(total_br)
    target_session["total_artifacts"] = int(total_art)
    target_session["last_activity_at"] = now
    target_session["updated_at"] = now
    sessions[target_session_idx] = target_session

    # ---- Persist all changes (single commit phase)
    _save("sessions.json", sessions)
    if isinstance(thoughts, list):
        _save("thoughts.json", thoughts)
    if isinstance(artifacts, list):
        _save("artifacts.json", artifacts)
    if isinstance(col_sessions, list):
        _save("collaboration_sessions.json", col_sessions)
    if isinstance(col_entities, list):
        _save("collaboration_entities.json", col_entities)
    if isinstance(sci_inq, list):
        _save("scientific_inquiries.json", sci_inq)

    _append_request_log(
        "ok",
        credential=cred.get("id"),
        meta={
            "session_id": target_session_id,
            "merge": merge,
            "imported": {
                "thoughts": imported_thoughts,
                "artifacts": imported_artifacts,
                "collaboration_sessions": imported_col_sessions,
                "collaboration_entities": imported_col_entities,
                "scientific_inquiries": imported_inq,
            },
        },
    )

    return {"session": target_session, "imported": {"thoughts": imported_thoughts, "artifacts": imported_artifacts, "collaboration_sessions": imported_col_sessions, "collaboration_entities": imported_col_entities, "scientific_inquiries": imported_inq}}
